insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('ca000000-0000-0000-0000-000000000001', 'ukmla', '6720bdff-175a-431c-b56e-254338c23e99',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('ca000000-0000-0000-0000-000000000001', 'A', 'Reassure and start oral ferrous sulfate empirically without further investigation', false, 'Ruled out because treating empirically without investigating the cause risks missing an underlying GI malignancy, which is the priority in a man of this age with unexplained iron deficiency.', 1),
('ca000000-0000-0000-0000-000000000001', 'B', 'Upper and lower GI endoscopy (bidirectional endoscopy)', true, 'Correct. Iron deficiency anaemia in a man of this age without an obvious cause is assumed to result from GI blood loss until proven otherwise; urgent bidirectional endoscopy is the appropriate next step to exclude colorectal or upper GI malignancy.', 2),
('ca000000-0000-0000-0000-000000000001', 'C', 'Coeliac serology alone with no endoscopy', false, 'Ruled out because coeliac disease is a recognised cause of iron deficiency anaemia and should be tested for, but this alone would miss colorectal malignancy; bidirectional endoscopy remains essential.', 3),
('ca000000-0000-0000-0000-000000000001', 'D', 'Bone marrow biopsy', false, 'Ruled out because this is not first-line for straightforward iron deficiency anaemia; the priority is to find the source of blood loss.', 4),
('ca000000-0000-0000-0000-000000000001', 'E', 'Serum protein electrophoresis', false, 'Ruled out because this looks for myeloma, not the cause of iron deficiency anaemia; it is irrelevant here.', 5),
('ca000000-0000-0000-0000-000000000002', 'A', 'Oral folic acid replacement alone', false, 'Ruled out because giving folate without correcting B12 deficiency can worsen neurological damage by fuelling erythropoiesis without the B12 needed for neurological function, precipitating subacute combined degeneration.', 1),
('ca000000-0000-0000-0000-000000000002', 'B', 'Oral ferrous sulfate', false, 'Ruled out because iron does not address a macrocytic anaemia due to B12 deficiency; iron is used for microcytic anaemia.', 2),
('ca000000-0000-0000-0000-000000000002', 'C', 'Watchful waiting with repeat bloods in 3 months', false, 'Ruled out because this risks ongoing, progressive, and potentially irreversible neurological damage; treatment should not be delayed.', 3),
('ca000000-0000-0000-0000-000000000002', 'D', 'Intramuscular hydroxocobalamin replacement', true, 'Correct. B12 must be replaced to treat and prevent progression of the neurological complications; folate given alone or before B12 correction risks precipitating or worsening subacute combined degeneration of the cord.', 4),
('ca000000-0000-0000-0000-000000000002', 'E', 'Blood transfusion', false, 'Ruled out because transfusion is not indicated for chronic, stable anaemia without haemodynamic compromise; replacing the underlying deficiency is the appropriate first-line management.', 5),
('ca000000-0000-0000-0000-000000000003', 'A', 'Oral folic acid replacement, continued alongside routine pregnancy folic acid supplementation', true, 'Correct. Folate deficiency in pregnancy should be treated with folic acid replacement; malabsorption from poorly controlled coeliac disease is a likely contributing cause here and should also be addressed.', 1),
('ca000000-0000-0000-0000-000000000003', 'B', 'Intramuscular hydroxocobalamin', false, 'Ruled out because B12 is normal, so replacing it is unnecessary; the deficiency identified here is folate, not B12.', 2),
('ca000000-0000-0000-0000-000000000003', 'C', 'No treatment needed, as this is physiological dilutional anaemia of pregnancy', false, 'Ruled out because dilutional anaemia does not typically cause significant macrocytosis or a low red cell folate; a true folate deficiency requiring treatment is present.', 3),
('ca000000-0000-0000-0000-000000000003', 'D', 'Stop gluten-free diet advice as it is not relevant in pregnancy', false, 'Ruled out because continuing a strict gluten-free diet is important to treat the underlying coeliac disease driving malabsorption.', 4),
('ca000000-0000-0000-0000-000000000003', 'E', 'Immediate blood transfusion', false, 'Ruled out because transfusion is not warranted for asymptomatic, mild-to-moderate anaemia; correcting the deficiency is the appropriate management.', 5),
('ca000000-0000-0000-0000-000000000004', 'A', 'Iron deficiency anaemia due to GI blood loss', false, 'Ruled out because ferritin is raised, not low, and TIBC is low rather than the raised TIBC typically seen in true iron deficiency.', 1),
('ca000000-0000-0000-0000-000000000004', 'B', 'Methotrexate-induced bone marrow suppression', false, 'Ruled out because this would more typically cause pancytopenia or macrocytosis rather than this normocytic, inflammatory iron-study pattern; no other cytopenias are described.', 2),
('ca000000-0000-0000-0000-000000000004', 'C', 'Anaemia of chronic disease secondary to rheumatoid arthritis', true, 'Correct. Chronic inflammation raises hepcidin, which reduces iron release from macrophage stores and gut absorption, producing a normocytic anaemia with low iron, low TIBC, and normal/raised ferritin (an acute phase protein).', 3),
('ca000000-0000-0000-0000-000000000004', 'D', 'B12 deficiency', false, 'Ruled out because the anaemia here is normocytic, not macrocytic.', 4),
('ca000000-0000-0000-0000-000000000004', 'E', 'Haemolytic anaemia', false, 'Ruled out because there is no evidence of jaundice, raised bilirubin, or reticulocytosis; the iron study pattern fits inflammation, not haemolysis.', 5),
('ca000000-0000-0000-0000-000000000005', 'A', 'Hereditary spherocytosis', false, 'Ruled out because the direct antiglobulin test would be negative in an inherited membrane disorder; a positive DAT points to an immune (acquired) cause.', 1),
('ca000000-0000-0000-0000-000000000005', 'B', 'G6PD deficiency', false, 'Ruled out because this is an X-linked enzyme defect usually triggered by oxidative stressors (infection, drugs, fava beans), and would not cause a positive direct antiglobulin test.', 2),
('ca000000-0000-0000-0000-000000000005', 'C', 'Iron deficiency anaemia', false, 'Ruled out because the clinical/laboratory picture (jaundice, raised bilirubin/LDH, low haptoglobin, reticulocytosis, positive DAT) indicates haemolysis, not iron deficiency.', 3),
('ca000000-0000-0000-0000-000000000005', 'D', 'Thrombotic thrombocytopenic purpura', false, 'Ruled out because TTP causes microangiopathic haemolysis with schistocytes and thrombocytopenia, and the direct antiglobulin test is typically negative; here spherocytes and a positive DAT are described instead.', 4),
('ca000000-0000-0000-0000-000000000005', 'E', 'Warm autoimmune haemolytic anaemia', true, 'Correct. The combination of a positive direct antiglobulin test, spherocytes, raised bilirubin/LDH, low haptoglobin, and reticulocytosis in a patient with an autoimmune disease (SLE) is characteristic of warm-type AIHA, mediated by IgG autoantibodies.', 5),
('ca000000-0000-0000-0000-000000000006', 'A', 'Warm autoimmune haemolytic anaemia', false, 'Ruled out because the direct antiglobulin test is negative, whereas AIHA typically shows a positive DAT.', 1),
('ca000000-0000-0000-0000-000000000006', 'B', 'Hereditary spherocytosis', false, 'Ruled out because the trigger (oxidant drug) and blood film findings (Heinz bodies, bite cells rather than spherocytes) point to an enzyme defect, not a membrane disorder.', 2),
('ca000000-0000-0000-0000-000000000006', 'C', 'Glucose-6-phosphate dehydrogenase (G6PD) deficiency', true, 'Correct. Acute haemolysis triggered by an oxidant drug (nitrofurantoin), with Heinz bodies/bite cells and a negative direct antiglobulin test, is classic for G6PD deficiency, an X-linked enzymopathy more common in Mediterranean, African, and Asian populations.', 3),
('ca000000-0000-0000-0000-000000000006', 'D', 'Sickle cell disease', false, 'Ruled out because there is no history of sickle cell disease and the blood film does not describe sickle cells; the acute oxidative haemolysis pattern fits G6PD deficiency.', 4),
('ca000000-0000-0000-0000-000000000006', 'E', 'Iron deficiency anaemia', false, 'Ruled out because the presentation is of acute haemolysis (dark urine, jaundice, sudden drop from baseline Hb) rather than a chronic microcytic anaemia.', 5),
('ca000000-0000-0000-0000-000000000007', 'A', 'Withhold opioid analgesia due to concerns about dependence, and manage with paracetamol alone', false, 'Ruled out because inadequate analgesia is a well-recognised harm in sickle crisis; opioids are appropriately used for severe vaso-occlusive pain and should not be withheld.', 1),
('ca000000-0000-0000-0000-000000000007', 'B', 'Immediate exchange blood transfusion regardless of severity', false, 'Ruled out because exchange transfusion is reserved for specific severe complications (e.g. acute chest syndrome, stroke), not routine uncomplicated painful crisis.', 2),
('ca000000-0000-0000-0000-000000000007', 'C', 'Discharge home with oral analgesia, as sickle crises can be managed in the community', false, 'Ruled out because this presentation, with fever and significant pain, needs hospital assessment and prompt treatment, particularly with a possible infective trigger.', 3),
('ca000000-0000-0000-0000-000000000007', 'D', 'Prompt analgesia (strong opioid analgesia), oxygen if hypoxic, and IV fluids, with investigation for a precipitant such as infection', true, 'Correct. Acute vaso-occlusive crisis requires rapid, adequate analgesia (often opioids), hydration, oxygen if hypoxic, and a search for and treatment of a precipitant (e.g. infection), which should not be delayed.', 4),
('ca000000-0000-0000-0000-000000000007', 'E', 'Broad-spectrum antibiotics without analgesia as the priority', false, 'Ruled out because while sepsis/infection should be investigated and treated if present, analgesia is an immediate priority and must not be deprioritised.', 5),
('ca000000-0000-0000-0000-000000000008', 'A', 'Oral iron replacement', false, 'Ruled out because ferritin is normal, indicating iron stores are adequate; this is not iron deficiency anaemia and iron would not correct the underlying globin chain abnormality.', 1),
('ca000000-0000-0000-0000-000000000008', 'B', 'Bone marrow biopsy', false, 'Ruled out because this is not required for this classic presentation; a targeted haemoglobinopathy screen is appropriate first.', 2),
('ca000000-0000-0000-0000-000000000008', 'C', 'Reassure and no further investigation', false, 'Ruled out because confirming the diagnosis is important for genetic counselling (partner testing, reproductive risk of thalassaemia major in offspring).', 3),
('ca000000-0000-0000-0000-000000000008', 'D', 'Vitamin B12 and folate levels', false, 'Ruled out because this is a microcytic (not macrocytic) picture, making B12/folate deficiency unlikely to be the cause.', 4),
('ca000000-0000-0000-0000-000000000008', 'E', 'Haemoglobin electrophoresis', true, 'Correct. A disproportionately low MCV relative to a near-normal Hb, with normal ferritin, in a patient from a population where thalassaemia is common, points towards thalassaemia trait; haemoglobin electrophoresis (or HPLC) is used to characterise the haemoglobin variant.', 5),
('ca000000-0000-0000-0000-000000000009', 'A', 'Absolute iron deficiency due to occult GI bleeding, with ferritin reliably excluding this', false, 'Ruled out because ferritin here (250 ug/L) is an acute-phase reactant raised by the inflammatory state of CKD, and does not reliably exclude iron deficiency; a low transferrin saturation still suggests iron-restricted erythropoiesis.', 1),
('ca000000-0000-0000-0000-000000000009', 'B', 'Functional iron deficiency in the context of chronic kidney disease/chronic inflammation, where ferritin is unreliable as a marker of true iron stores', true, 'Correct. In CKD, ferritin is often elevated due to chronic inflammation despite true or functional iron deficiency, so transferrin saturation is a more useful marker; a transferrin saturation of 15% suggests iron-restricted erythropoiesis warranting iron assessment even with high ferritin.', 2),
('ca000000-0000-0000-0000-000000000009', 'C', 'Pure erythropoietin deficiency with normal iron status requiring no iron work-up', false, 'Ruled out because while erythropoietin deficiency contributes to CKD anaemia, the low transferrin saturation indicates a concurrent iron-restricted state that should be assessed before/alongside erythropoiesis-stimulating therapy.', 3),
('ca000000-0000-0000-0000-000000000009', 'D', 'Thalassaemia trait', false, 'Ruled out because there is no mention of ethnic background, family history, or a pattern (very low MCV with normal-high Hb) suggestive of thalassaemia; this is a CKD-related anaemia picture.', 4),
('ca000000-0000-0000-0000-000000000009', 'E', 'Haemolysis', false, 'Ruled out because no evidence of raised bilirubin, LDH, or reticulocytosis is given; the picture described is one of iron indices, not haemolytic markers.', 5),
('ca000000-0000-0000-0000-000000000010', 'A', 'Serum vitamin B12 and folate levels', true, 'Correct. This is a megaloblastic anaemia (macrocytosis, hypersegmented neutrophils) and, given his history of gastric surgery predisposing to B12 malabsorption, B12 and folate levels should be measured before starting empirical replacement, to guide and confirm appropriate treatment.', 1),
('ca000000-0000-0000-0000-000000000010', 'B', 'Start empirical oral folic acid alone without checking levels', false, 'Ruled out because treating with folate before establishing B12 status risks masking or worsening a coexisting B12 deficiency and precipitating neurological complications.', 2),
('ca000000-0000-0000-0000-000000000010', 'C', 'Bone marrow aspirate as the first-line test', false, 'Ruled out because this is not required as first-line; peripheral blood tests (B12, folate) alongside the clinical picture are sufficient to guide initial management in most cases.', 3),
('ca000000-0000-0000-0000-000000000010', 'D', 'Anti-tissue transglutaminase antibodies only', false, 'Ruled out because this tests for coeliac disease, which is not directly suggested by his surgical history and clinical picture pointing more towards B12 malabsorption post-gastrectomy.', 4),
('ca000000-0000-0000-0000-000000000010', 'E', 'Immediate blood transfusion', false, 'Ruled out because transfusion is not indicated as a first step for a chronic, non-life-threatening anaemia; establishing the cause first is appropriate.', 5),
('ca000000-0000-0000-0000-000000000011', 'A', 'Von Willebrand disease', false, 'Ruled out because vWD more typically causes mucocutaneous bleeding (epistaxis, menorrhagia, bruising) rather than isolated haemarthrosis, and has autosomal inheritance rather than the X-linked pattern suggested here.', 1),
('ca000000-0000-0000-0000-000000000011', 'B', 'Immune thrombocytopenic purpura', false, 'Ruled out because the platelet count is normal here; ITP causes thrombocytopenia with normal coagulation times.', 2),
('ca000000-0000-0000-0000-000000000011', 'C', 'Haemophilia A (factor VIII deficiency)', true, 'Correct. An X-linked recessive bleeding disorder presenting with haemarthrosis after minor trauma, a prolonged APTT with normal PT and platelet count, and a family history consistent with X-linked inheritance is classic for haemophilia A.', 3),
('ca000000-0000-0000-0000-000000000011', 'D', 'Vitamin K deficiency', false, 'Ruled out because this would prolong both PT and APTT (via factors II, VII, IX, X), not cause an isolated APTT prolongation.', 4),
('ca000000-0000-0000-0000-000000000011', 'E', 'Non-accidental injury', false, 'Ruled out because, while always important to consider, the isolated haemarthrosis pattern with prolonged APTT and family history strongly points to an inherited coagulation factor deficiency as the primary diagnosis to investigate first.', 5),
('ca000000-0000-0000-0000-000000000012', 'A', 'Haemophilia A', false, 'Ruled out because haemophilia A predominantly affects males (X-linked) and causes deep bleeding (haemarthrosis) rather than the mucocutaneous bleeding pattern described here.', 1),
('ca000000-0000-0000-0000-000000000012', 'B', 'Von Willebrand disease', true, 'Correct. Mucocutaneous bleeding (menorrhagia, bruising, post-dental bleeding) since a young age, with normal platelet count, normal PT, and mildly prolonged APTT (due to reduced factor VIII, which von Willebrand factor normally stabilises), is characteristic of von Willebrand disease, the most common inherited bleeding disorder.', 2),
('ca000000-0000-0000-0000-000000000012', 'C', 'Immune thrombocytopenic purpura', false, 'Ruled out because the platelet count is normal; ITP causes thrombocytopenia.', 3),
('ca000000-0000-0000-0000-000000000012', 'D', 'Disseminated intravascular coagulation', false, 'Ruled out because there is no acute critical illness or trigger described, and DIC would show prolonged PT and APTT with low fibrinogen and thrombocytopenia, not this chronic pattern.', 4),
('ca000000-0000-0000-0000-000000000012', 'E', 'Factor XIII deficiency', false, 'Ruled out because this rare cause of delayed bleeding with a normal PT/APTT/platelet count fits less well than von Willebrand disease with this classic mucocutaneous bleeding history and mild APTT prolongation.', 5),
('ca000000-0000-0000-0000-000000000013', 'A', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes isolated thrombocytopenia with normal PT, APTT, and fibrinogen; here multiple coagulation parameters are deranged.', 1),
('ca000000-0000-0000-0000-000000000013', 'B', 'Haemophilia A', false, 'Ruled out because haemophilia is an inherited isolated factor VIII deficiency causing isolated APTT prolongation, not this global consumptive coagulopathy with thrombocytopenia and low fibrinogen in the setting of acute sepsis.', 2),
('ca000000-0000-0000-0000-000000000013', 'C', 'Vitamin K deficiency', false, 'Ruled out because this would not cause thrombocytopenia or markedly raised D-dimer; it affects only vitamin K-dependent factors.', 3),
('ca000000-0000-0000-0000-000000000013', 'D', 'Liver failure alone', false, 'Ruled out because, while liver failure can cause coagulopathy, the acute sepsis trigger and markedly raised D-dimer with this constellation strongly favour DIC as the primary process here.', 4),
('ca000000-0000-0000-0000-000000000013', 'E', 'Disseminated intravascular coagulation', true, 'Correct. In the context of severe sepsis, the combination of thrombocytopenia, prolonged PT and APTT, low fibrinogen, and markedly raised D-dimer, with bleeding from multiple sites, is characteristic of DIC, where widespread activation of coagulation consumes clotting factors and platelets.', 5),
('ca000000-0000-0000-0000-000000000014', 'A', 'Stop warfarin and give intravenous vitamin K and prothrombin complex concentrate', true, 'Correct. In life-threatening major bleeding on warfarin, immediate reversal is required using IV vitamin K (to restore ongoing synthesis of vitamin K-dependent factors) together with prothrombin complex concentrate (which rapidly replaces the deficient factors), alongside resuscitation.', 1),
('ca000000-0000-0000-0000-000000000014', 'B', 'Stop warfarin and observe, rechecking INR in 24 hours', false, 'Ruled out because this delay is inappropriate in the context of life-threatening bleeding; rapid reversal is required.', 2),
('ca000000-0000-0000-0000-000000000014', 'C', 'Give fresh frozen plasma alone without vitamin K', false, 'Ruled out because FFP alone provides a less concentrated and slower factor replacement than PCC, and vitamin K is needed to sustain factor correction; PCC plus vitamin K is preferred for major bleeding.', 3),
('ca000000-0000-0000-0000-000000000014', 'D', 'Continue warfarin at a reduced dose', false, 'Ruled out because continuing an anticoagulant during life-threatening haemorrhage is inappropriate; anticoagulation must be reversed.', 4),
('ca000000-0000-0000-0000-000000000014', 'E', 'Give protamine sulfate', false, 'Ruled out because protamine reverses heparin, not warfarin; it has no role in warfarin reversal.', 5),
('ca000000-0000-0000-0000-000000000015', 'A', 'Acute lymphoblastic leukaemia', false, 'Ruled out because there are no other cytopenias, no blasts on film, and no hepatosplenomegaly or lymphadenopathy, which would be more suggestive of marrow infiltration by leukaemia.', 1),
('ca000000-0000-0000-0000-000000000015', 'B', 'Disseminated intravascular coagulation', false, 'Ruled out because the child is well with an isolated thrombocytopenia and no coagulopathy or clinical evidence of a triggering critical illness.', 2),
('ca000000-0000-0000-0000-000000000015', 'C', 'Haemolytic uraemic syndrome', false, 'Ruled out because there is no diarrhoeal illness, anaemia, or renal impairment described, which would be expected in HUS alongside thrombocytopenia.', 3),
('ca000000-0000-0000-0000-000000000015', 'D', 'Immune thrombocytopenic purpura', true, 'Correct. Acute, isolated thrombocytopenia in an otherwise well child following a recent viral infection, with no other cytopenias, organomegaly, or blasts, is characteristic of childhood ITP, caused by immune-mediated platelet destruction.', 4),
('ca000000-0000-0000-0000-000000000015', 'E', 'Non-accidental injury', false, 'Ruled out because, while always worth considering with bruising in a child, the pattern of petechiae and isolated thrombocytopenia following a viral illness, without other suspicious features, is most consistent with ITP.', 5),
('ca000000-0000-0000-0000-000000000016', 'A', 'Haemophilia A', false, 'Ruled out because haemophilia causes isolated APTT prolongation with normal PT, whereas here both PT and APTT are prolonged.', 1),
('ca000000-0000-0000-0000-000000000016', 'B', 'Immune thrombocytopenic purpura', false, 'Ruled out because the platelet count is normal; this presentation is a coagulation factor problem, not a platelet disorder.', 2),
('ca000000-0000-0000-0000-000000000016', 'C', 'Vitamin K deficiency bleeding of the newborn', true, 'Correct. Neonates who do not receive prophylactic vitamin K are at risk of bleeding due to deficiency of the vitamin K-dependent clotting factors (II, VII, IX, X), causing prolonged PT and APTT with normal platelets and fibrinogen; exclusive breastfeeding increases this risk.', 3),
('ca000000-0000-0000-0000-000000000016', 'D', 'Disseminated intravascular coagulation', false, 'Ruled out because fibrinogen is normal and there is no evidence of an underlying critical illness/sepsis triggering a consumptive coagulopathy.', 4),
('ca000000-0000-0000-0000-000000000016', 'E', 'Von Willebrand disease', false, 'Ruled out because vWD does not typically prolong PT, and the clinical context (no vitamin K prophylaxis, breastfed) fits vitamin K deficiency far better.', 5),
('ca000000-0000-0000-0000-000000000017', 'A', 'Urgent plasma exchange', true, 'Correct. The combination of microangiopathic haemolytic anaemia (schistocytes, raised LDH, negative DAT), severe thrombocytopenia, neurological symptoms, and renal impairment, with a normal coagulation screen, is characteristic of thrombotic thrombocytopenic purpura, requiring urgent plasma exchange.', 1),
('ca000000-0000-0000-0000-000000000017', 'B', 'Platelet transfusion as first-line treatment', false, 'Ruled out because platelet transfusion can worsen microthrombus formation in TTP and is generally avoided unless there is life-threatening bleeding; plasma exchange is the priority treatment.', 2),
('ca000000-0000-0000-0000-000000000017', 'C', 'Anticoagulation with heparin', false, 'Ruled out because TTP is a microthrombotic condition and anticoagulation is not the primary treatment; plasma exchange takes priority.', 3),
('ca000000-0000-0000-0000-000000000017', 'D', 'Broad-spectrum antibiotics as first-line treatment', false, 'Ruled out because, while sepsis should be considered and excluded, the described picture (schistocytes, thrombocytopenia, normal coagulation screen, neurological/renal involvement) is classic for TTP, which requires urgent plasma exchange rather than antibiotics as the primary intervention.', 4),
('ca000000-0000-0000-0000-000000000017', 'E', 'Reassurance and outpatient follow-up', false, 'Ruled out because TTP is a medical emergency with high mortality if untreated; urgent inpatient management is required.', 5),
('ca000000-0000-0000-0000-000000000018', 'A', 'Continue heparin at a reduced dose', false, 'Ruled out because continuing heparin in suspected HIT perpetuates the immune-mediated prothrombotic process and risks further thrombosis.', 1),
('ca000000-0000-0000-0000-000000000018', 'B', 'Stop heparin and give no further anticoagulation', false, 'Ruled out because HIT is a prothrombotic state despite thrombocytopenia, and stopping anticoagulation entirely leaves the patient at high risk of further thrombosis; an alternative anticoagulant is needed.', 2),
('ca000000-0000-0000-0000-000000000018', 'C', 'Platelet transfusion', false, 'Ruled out because platelet transfusion is generally avoided in HIT, as it does not address the underlying process and may increase thrombotic risk.', 3),
('ca000000-0000-0000-0000-000000000018', 'D', 'Stop all heparin products and start a non-heparin anticoagulant', true, 'Correct. A falling platelet count (typically 5-10 days after heparin exposure) associated with new thrombosis (including skin necrosis at injection sites) is characteristic of heparin-induced thrombocytopenia; all heparin must be stopped immediately and replaced with an alternative (non-heparin) anticoagulant, as the ongoing prothrombotic state still requires anticoagulation.', 4),
('ca000000-0000-0000-0000-000000000018', 'E', 'Switch to low molecular weight heparin', false, 'Ruled out because low molecular weight heparin can still cross-react and is not a safe substitute in suspected HIT; a non-heparin anticoagulant should be used instead.', 5),
('ca000000-0000-0000-0000-000000000019', 'A', 'Vitamin K', false, 'Ruled out because dabigatran is a direct thrombin inhibitor, not a vitamin K antagonist; vitamin K has no reversal effect on dabigatran.', 1),
('ca000000-0000-0000-0000-000000000019', 'B', 'Idarucizumab', true, 'Correct. Idarucizumab is a monoclonal antibody fragment that specifically and rapidly reverses the anticoagulant effect of dabigatran, and is indicated in life-threatening bleeding such as intracranial haemorrhage.', 2),
('ca000000-0000-0000-0000-000000000019', 'C', 'Protamine sulfate', false, 'Ruled out because protamine reverses heparin, not dabigatran.', 3),
('ca000000-0000-0000-0000-000000000019', 'D', 'Fresh frozen plasma alone', false, $x$Ruled out because FFP does not reliably or specifically reverse dabigatran's anticoagulant effect; a specific reversal agent is preferred when available.$x$, 4),
('ca000000-0000-0000-0000-000000000019', 'E', 'Desmopressin', false, 'Ruled out because desmopressin raises von Willebrand factor and factor VIII, which is not relevant to reversing a direct thrombin inhibitor.', 5),
('ca000000-0000-0000-0000-000000000020', 'A', 'Undiagnosed haemophilia A', false, 'Ruled out because haemophilia causes an isolated prolonged APTT, which is normal here; the clinical picture instead fits a platelet function effect from aspirin.', 1),
('ca000000-0000-0000-0000-000000000020', 'B', 'Vitamin K deficiency', false, 'Ruled out because this would prolong PT and APTT, which are normal here.', 2),
('ca000000-0000-0000-0000-000000000020', 'C', 'Disseminated intravascular coagulation', false, 'Ruled out because there is no acute critical illness, and platelet count/PT/APTT are all normal, whereas DIC causes derangement across these parameters.', 3),
('ca000000-0000-0000-0000-000000000020', 'D', 'Factor V Leiden mutation', false, 'Ruled out because this causes a prothrombotic (not bleeding) tendency, and would not explain post-extraction bleeding.', 4),
('ca000000-0000-0000-0000-000000000020', 'E', 'Aspirin irreversibly inhibits platelet cyclo-oxygenase, impairing platelet aggregation despite a normal platelet count and normal clotting screen', true, 'Correct. Aspirin irreversibly inhibits cyclo-oxygenase-1 in platelets, reducing thromboxane A2 production and impairing platelet aggregation; this causes a qualitative platelet function defect that does not show up as an abnormality in platelet count, PT, or APTT, but can cause mild prolonged bleeding, particularly from mucosal surfaces.', 5),
('ca000000-0000-0000-0000-000000000021', 'A', 'Reassure the family and review again in 2 weeks', false, 'Ruled out because this presentation is a red flag for acute leukaemia requiring urgent, not delayed, specialist assessment.', 1),
('ca000000-0000-0000-0000-000000000021', 'B', 'Start oral antibiotics for presumed viral/bacterial infection and review in a week', false, 'Ruled out because, while fever can accompany leukaemia, the blast cells and cytopenias require urgent haematological work-up rather than a delayed review for a presumed infection.', 2),
('ca000000-0000-0000-0000-000000000021', 'C', 'Arrange outpatient iron studies for presumed iron deficiency anaemia', false, 'Ruled out because the combination of blasts, bone pain, organomegaly, and multiple cytopenias is not consistent with simple iron deficiency and needs urgent oncological assessment.', 3),
('ca000000-0000-0000-0000-000000000021', 'D', 'Urgent same-day referral to paediatric haematology/oncology for further assessment including bone marrow examination', true, 'Correct. The combination of pallor, bruising, bone pain, lymphadenopathy, hepatosplenomegaly, and circulating blast cells with cytopenias in a child is highly suspicious for acute lymphoblastic leukaemia, requiring urgent same-day specialist referral for confirmatory bone marrow examination and treatment planning.', 4),
('ca000000-0000-0000-0000-000000000021', 'E', 'Give a course of oral corticosteroids in primary care before any specialist review', false, 'Ruled out because steroids should not be given prior to a definitive diagnosis in suspected leukaemia, as they can interfere with diagnostic bone marrow findings and are managed within specialist protocols only.', 5),
('ca000000-0000-0000-0000-000000000022', 'A', 'Chronic myeloid leukaemia', false, 'Ruled out because CML typically presents with a markedly raised WCC with a spectrum of maturing myeloid cells and splenomegaly, not pancytopenia with abnormal promyelocytes and DIC.', 1),
('ca000000-0000-0000-0000-000000000022', 'B', 'Acute promyelocytic leukaemia (a subtype of acute myeloid leukaemia) complicated by disseminated intravascular coagulation', true, 'Correct. Abnormal promyelocytes on blood film with concurrent DIC (prolonged PT/APTT, low fibrinogen, raised D-dimer) and severe bleeding is characteristic of acute promyelocytic leukaemia, a haematological emergency due to its strong association with coagulopathy.', 2),
('ca000000-0000-0000-0000-000000000022', 'C', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes isolated thrombocytopenia with a normal coagulation screen and no abnormal blast/promyelocyte population on film.', 3),
('ca000000-0000-0000-0000-000000000022', 'D', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL presents with a mature lymphocytosis in older adults, not blast/promyelocyte infiltration with pancytopenia and DIC.', 4),
('ca000000-0000-0000-0000-000000000022', 'E', 'Aplastic anaemia', false, 'Ruled out because aplastic anaemia causes pancytopenia due to marrow failure without abnormal circulating promyelocytes or a consumptive coagulopathy.', 5),
('ca000000-0000-0000-0000-000000000023', 'A', 'Acute lymphoblastic leukaemia', false, 'Ruled out because ALL typically presents acutely with cytopenias, blast cells (not mature lymphocytes), and systemic symptoms, most commonly in children, unlike this indolent presentation in an asymptomatic older adult.', 1),
('ca000000-0000-0000-0000-000000000023', 'B', 'Infectious mononucleosis', false, 'Ruled out because this typically affects younger patients with an acute febrile illness, sore throat, and atypical (reactive) lymphocytes, not the chronic, asymptomatic pattern with smudge cells seen here.', 2),
('ca000000-0000-0000-0000-000000000023', 'C', 'Chronic myeloid leukaemia', false, 'Ruled out because CML causes a granulocytosis with a full spectrum of maturing myeloid cells and often marked splenomegaly, not a lymphocytosis of mature small lymphocytes.', 3),
('ca000000-0000-0000-0000-000000000023', 'D', 'Hairy cell leukaemia', false, $x$Ruled out because this rare, distinct leukaemia typically presents with pancytopenia and splenomegaly, with characteristic 'hairy' cells on film, rather than the marked lymphocytosis with smudge cells described here.$x$, 4),
('ca000000-0000-0000-0000-000000000023', 'E', 'Chronic lymphocytic leukaemia', true, $x$Correct. An incidental, marked lymphocytosis of mature small lymphocytes with characteristic 'smudge cells' on blood film, in an asymptomatic older adult with mild lymphadenopathy, is the classic presentation of chronic lymphocytic leukaemia, often diagnosed on routine bloods.$x$, 5),
('ca000000-0000-0000-0000-000000000024', 'A', 'Urgent excision lymph node biopsy', true, 'Correct. Painless, rubbery lymphadenopathy with B symptoms (fever, night sweats, weight loss) and the classic (though not universal) history of alcohol-induced lymph node pain in a young adult is suspicious for Hodgkin lymphoma; excision biopsy of the lymph node is required to confirm the diagnosis (looking for Reed-Sternberg cells) and guide staging.', 1),
('ca000000-0000-0000-0000-000000000024', 'B', 'Fine needle aspiration only, with no further biopsy needed', false, 'Ruled out because fine needle aspiration typically provides insufficient architecture to reliably diagnose lymphoma; excision biopsy is needed to assess nodal architecture and identify Reed-Sternberg cells.', 2),
('ca000000-0000-0000-0000-000000000024', 'C', 'Reassure and review in 3 months, as lymphadenopathy in young adults is usually reactive', false, 'Ruled out because the persistent, enlarging nature of the lymphadenopathy with systemic B symptoms and the length of history (3 months) are red flags requiring prompt investigation, not watchful waiting.', 3),
('ca000000-0000-0000-0000-000000000024', 'D', 'Course of oral antibiotics for presumed bacterial lymphadenitis', false, 'Ruled out because there is no evidence of an acute infective source, and the chronic, painless, systemic symptom picture is not consistent with simple bacterial lymphadenitis.', 4),
('ca000000-0000-0000-0000-000000000024', 'E', 'Start empirical chemotherapy before tissue diagnosis', false, 'Ruled out because histological confirmation and staging are required before starting treatment for lymphoma; treatment should never be started without a tissue diagnosis.', 5),
('ca000000-0000-0000-0000-000000000025', 'A', 'Hodgkin lymphoma', false, 'Ruled out because the biopsy would classically show Reed-Sternberg cells within a mixed inflammatory background, not sheets of large atypical B cells as described.', 1),
('ca000000-0000-0000-0000-000000000025', 'B', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL is an indolent disease of mature small lymphocytes, not a rapidly growing mass of large atypical cells.', 2),
('ca000000-0000-0000-0000-000000000025', 'C', 'Diffuse large B-cell lymphoma (a subtype of non-Hodgkin lymphoma)', true, 'Correct. A rapidly growing lymph node mass with B symptoms and widespread lymphadenopathy, with biopsy showing sheets of large atypical B cells (rather than Reed-Sternberg cells), is characteristic of diffuse large B-cell lymphoma, the most common subtype of non-Hodgkin lymphoma.', 3),
('ca000000-0000-0000-0000-000000000025', 'D', 'Reactive lymphadenopathy secondary to infection', false, 'Ruled out because the biopsy demonstrates a clonal population of large atypical B cells, which is not consistent with a reactive process.', 4),
('ca000000-0000-0000-0000-000000000025', 'E', 'Metastatic carcinoma', false, 'Ruled out because the biopsy describes large atypical B cells (a lymphoid/haematological picture), not epithelial carcinoma cells.', 5),
('ca000000-0000-0000-0000-000000000026', 'A', 'Metastatic prostate cancer', false, 'Ruled out because bony metastases from prostate cancer are typically sclerotic rather than lytic, and would not typically be associated with a monoclonal paraprotein band.', 1),
('ca000000-0000-0000-0000-000000000026', 'B', 'Primary hyperparathyroidism', false, 'Ruled out because this would explain hypercalcaemia alone but does not account for the lytic lesions, paraprotein band, and anaemia seen together.', 2),
('ca000000-0000-0000-0000-000000000026', 'C', 'Osteoporosis with vertebral fracture', false, 'Ruled out because osteoporosis alone does not cause hypercalcaemia, renal impairment, or a monoclonal paraprotein band.', 3),
('ca000000-0000-0000-0000-000000000026', 'D', 'Multiple myeloma', true, $x$Correct. The combination of bone pain with lytic lesions, anaemia, hypercalcaemia, renal impairment, and a monoclonal paraprotein band (the classic 'CRAB' features) is characteristic of multiple myeloma, a plasma cell malignancy.$x$, 4),
('ca000000-0000-0000-0000-000000000026', 'E', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL causes a mature lymphocytosis, not lytic bone lesions or a paraprotein band; the clinical/laboratory picture here is classic for a plasma cell disorder.', 5),
('ca000000-0000-0000-0000-000000000027', 'A', 'Wait for blood culture and neutrophil count results before starting antibiotics', false, 'Ruled out because delaying antibiotics in suspected neutropenic sepsis significantly increases mortality; treatment must not wait for confirmatory results.', 1),
('ca000000-0000-0000-0000-000000000027', 'B', 'Discharge home with oral antibiotics and outpatient follow-up', false, 'Ruled out because neutropenic sepsis requires immediate hospital assessment and IV antibiotic treatment, not outpatient management.', 2),
('ca000000-0000-0000-0000-000000000027', 'C', 'Immediate empirical broad-spectrum intravenous antibiotics without waiting for blood culture results, within 1 hour of arrival', true, 'Correct. Fever in a patient who is neutropenic following recent chemotherapy is neutropenic sepsis until proven otherwise, a life-threatening emergency; empirical broad-spectrum IV antibiotics must be started immediately (within 1 hour) after taking cultures, without waiting for microbiology results.', 3),
('ca000000-0000-0000-0000-000000000027', 'D', 'Give antipyretics only and observe for 24 hours', false, 'Ruled out because this delays essential antimicrobial treatment in a life-threatening emergency.', 4),
('ca000000-0000-0000-0000-000000000027', 'E', 'Arrange urgent bone marrow biopsy before treating', false, 'Ruled out because immediate treatment of suspected sepsis takes priority; a bone marrow biopsy is not part of the acute management of neutropenic sepsis.', 5),
('ca000000-0000-0000-0000-000000000028', 'A', 'Acute pyelonephritis', false, 'Ruled out because there is no evidence of urinary infection, and the specific electrolyte derangement pattern (raised potassium, phosphate, urate; low calcium) is not explained by pyelonephritis.', 1),
('ca000000-0000-0000-0000-000000000028', 'B', 'Tumour lysis syndrome', true, 'Correct. Rapid death of a large tumour burden after starting chemotherapy releases intracellular contents, causing the classic pattern of hyperkalaemia, hyperphosphataemia, hypocalcaemia, and hyperuricaemia, with resulting acute kidney injury; this is tumour lysis syndrome, most commonly seen with high-grade, rapidly proliferating tumours like Burkitt lymphoma.', 2),
('ca000000-0000-0000-0000-000000000028', 'C', 'Rhabdomyolysis unrelated to chemotherapy', false, 'Ruled out because, while rhabdomyolysis can cause hyperkalaemia and renal impairment, the clinical context (recent initiation of chemotherapy for a high-grade tumour) and combination of hyperphosphataemia, hypocalcaemia, and hyperuricaemia are specifically characteristic of tumour lysis syndrome.', 3),
('ca000000-0000-0000-0000-000000000028', 'D', 'Chronic kidney disease progression', false, 'Ruled out because this is an acute presentation temporally linked to starting chemotherapy for a high-grade lymphoma, not a chronic process.', 4),
('ca000000-0000-0000-0000-000000000028', 'E', 'Addisonian crisis', false, 'Ruled out because this would not explain the raised phosphate and urate, and the clinical context strongly points to tumour lysis syndrome following chemotherapy for a bulky, rapidly proliferating tumour.', 5),
('ca000000-0000-0000-0000-000000000029', 'A', 'Routine referral to paediatrics with an appointment in 6 weeks', false, 'Ruled out because these red flag features require urgent, not routine, assessment given the possibility of leukaemia.', 1),
('ca000000-0000-0000-0000-000000000029', 'B', 'Reassure the family that bruising is normal in active toddlers and discharge with no follow-up', false, 'Ruled out because the combination of pallor, unexplained bruising of varying ages, and splenomegaly are concerning red flag features that should not be dismissed.', 2),
('ca000000-0000-0000-0000-000000000029', 'C', 'Start oral iron supplementation empirically without blood tests', false, 'Ruled out because treating empirically without investigating risks missing a serious underlying diagnosis such as leukaemia.', 3),
('ca000000-0000-0000-0000-000000000029', 'D', 'Refer to safeguarding as the primary and only action, without any blood tests', false, 'Ruled out because, while non-accidental injury should always be considered with unexplained bruising, the combination of pallor, fatigue, and splenomegaly warrants urgent haematological investigation first/alongside, as this constellation is a recognised leukaemia red flag pattern.', 4),
('ca000000-0000-0000-0000-000000000029', 'E', 'Arrange a full blood count and film to be reviewed urgently the same day, with immediate referral if abnormal', true, 'Correct. Unexplained persistent tiredness, pallor, bruising, and splenomegaly in a child are red flag features for leukaemia; UK guidance recommends a very urgent (within 48 hours, and same-day where possible) full blood count, with immediate specialist referral if this suggests leukaemia.', 5),
('ca000000-0000-0000-0000-000000000030', 'A', 'Superior vena cava obstruction, most likely due to a mediastinal lymphoma, requiring urgent oncological assessment', true, 'Correct. Facial/neck swelling, distended neck veins, and dilated collateral chest wall veins, worsened by lying flat, in a young adult with an anterior mediastinal mass, is characteristic of superior vena cava obstruction, commonly caused in this age group by lymphoma; this requires urgent oncological assessment and tissue diagnosis to guide emergency treatment.', 1),
('ca000000-0000-0000-0000-000000000030', 'B', 'Simple heart failure with fluid overload', false, 'Ruled out because the pattern of facial/neck swelling with distended neck and chest wall collateral veins, together with a mediastinal mass on imaging, points to SVC obstruction rather than isolated cardiac failure.', 2),
('ca000000-0000-0000-0000-000000000030', 'C', 'Anaphylaxis', false, 'Ruled out because there is no history of an allergen exposure or acute onset over minutes, and the mediastinal mass on imaging points to a structural cause of venous obstruction.', 3),
('ca000000-0000-0000-0000-000000000030', 'D', 'Simple upper respiratory tract infection', false, 'Ruled out because the clinical findings (venous congestion pattern, mediastinal mass) are not consistent with a simple infective illness.', 4),
('ca000000-0000-0000-0000-000000000030', 'E', 'Bilateral pneumothorax', false, 'Ruled out because the clinical picture (facial swelling, distended neck/chest wall veins, mediastinal mass) is specific for venous obstruction, not lung collapse.', 5),
('ca000000-0000-0000-0000-000000000031', 'A', 'Secondary polycythaemia due to chronic hypoxia', false, 'Ruled out because secondary polycythaemia is driven by raised (not low) erythropoietin in response to hypoxia; the low erythropoietin here indicates an autonomous (primary) process.', 1),
('ca000000-0000-0000-0000-000000000031', 'B', 'Relative polycythaemia due to dehydration', false, 'Ruled out because this would not typically cause the panmyelosis (raised WCC and platelets too) or the low erythropoietin seen here, and the symptoms described are classic for PV.', 2),
('ca000000-0000-0000-0000-000000000031', 'C', 'Polycythaemia vera', true, 'Correct. A raised haemoglobin/haematocrit with mild leucocytosis and thrombocytosis, aquagenic pruritus, erythromelalgia (burning in the extremities), and a low erythropoietin level (as production is autonomous rather than driven by hypoxia) is characteristic of polycythaemia vera, a myeloproliferative neoplasm usually driven by a JAK2 mutation.', 3),
('ca000000-0000-0000-0000-000000000031', 'D', 'Iron deficiency anaemia', false, 'Ruled out because this causes a low, not high, haemoglobin.', 4),
('ca000000-0000-0000-0000-000000000031', 'E', 'Essential thrombocythaemia', false, 'Ruled out because the primary and most striking abnormality here is a very high haemoglobin/haematocrit, not an isolated marked thrombocytosis.', 5),
('ca000000-0000-0000-0000-000000000032', 'A', 'Reactive thrombocytosis secondary to iron deficiency', false, 'Ruled out because iron studies are normal here, making iron deficiency-driven reactive thrombocytosis unlikely.', 1),
('ca000000-0000-0000-0000-000000000032', 'B', 'Reactive thrombocytosis secondary to infection or inflammation', false, 'Ruled out because there is no evidence of an infective or inflammatory process to explain a reactive rise in platelets.', 2),
('ca000000-0000-0000-0000-000000000032', 'C', 'Polycythaemia vera', false, 'Ruled out because the haemoglobin is normal here, whereas PV is characterised by a raised haemoglobin/haematocrit as the primary finding.', 3),
('ca000000-0000-0000-0000-000000000032', 'D', 'Essential thrombocythaemia', true, 'Correct. A markedly raised platelet count with normal Hb and WCC, in the absence of a reactive cause, together with microvascular symptoms (digital erythromelalgia), is characteristic of essential thrombocythaemia, a myeloproliferative neoplasm.', 4),
('ca000000-0000-0000-0000-000000000032', 'E', 'Myelodysplastic syndrome', false, 'Ruled out because MDS typically causes cytopenias (not an isolated marked thrombocytosis) due to ineffective haematopoiesis.', 5),
('ca000000-0000-0000-0000-000000000033', 'A', 'Chronic myeloid leukaemia', false, $x$Ruled out because CML typically shows a markedly raised WCC with a full spectrum of maturing granulocytes and is usually confirmed by finding the BCR-ABL fusion/Philadelphia chromosome, rather than presenting with a 'dry tap' from marrow fibrosis.$x$, 1),
('ca000000-0000-0000-0000-000000000033', 'B', 'Primary myelofibrosis', true, $x$Correct. Massive splenomegaly, constitutional symptoms, teardrop cells (dacrocytes) with leucoerythroblastic blood film changes, and a 'dry tap' on bone marrow aspiration (due to marrow fibrosis) are characteristic of primary myelofibrosis, a myeloproliferative neoplasm.$x$, 2),
('ca000000-0000-0000-0000-000000000033', 'C', 'Hairy cell leukaemia', false, $x$Ruled out because this typically causes pancytopenia with characteristic 'hairy' cells, not the teardrop cells and leucoerythroblastic picture described here.$x$, 3),
('ca000000-0000-0000-0000-000000000033', 'D', 'Polycythaemia vera', false, 'Ruled out because Hb is low here rather than raised; PV features a raised haemoglobin/haematocrit, though it can progress to myelofibrosis over time.', 4),
('ca000000-0000-0000-0000-000000000033', 'E', 'Metastatic bone marrow infiltration from carcinoma', false, 'Ruled out because, while this can also cause a leucoerythroblastic film and dry tap, the combination of massive splenomegaly with these specific film findings and constitutional symptoms is most characteristic of primary myelofibrosis in this vignette.', 5),
('ca000000-0000-0000-0000-000000000034', 'A', 'Chronic myeloid leukaemia', true, 'Correct. A markedly raised white cell count with a full spectrum of maturing granulocytic precursors on blood film, basophilia, and massive splenomegaly, in a middle-aged adult, is classic for chronic myeloid leukaemia, typically driven by the BCR-ABL fusion gene (Philadelphia chromosome).', 1),
('ca000000-0000-0000-0000-000000000034', 'B', 'Acute myeloid leukaemia', false, 'Ruled out because AML typically presents with a predominance of blast cells and pancytopenia (marrow failure), rather than the full maturation spectrum of granulocytes seen here.', 2),
('ca000000-0000-0000-0000-000000000034', 'C', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL causes a lymphocytosis of mature small lymphocytes, not a granulocytic proliferation with a full maturation spectrum.', 3),
('ca000000-0000-0000-0000-000000000034', 'D', 'Reactive leucocytosis due to infection', false, 'Ruled out because a reactive leucocytosis would not typically reach this magnitude, nor cause massive splenomegaly with basophilia and a full spectrum of immature granulocytic forms.', 4),
('ca000000-0000-0000-0000-000000000034', 'E', 'Primary myelofibrosis', false, $x$Ruled out because this typically causes a leucoerythroblastic picture with teardrop cells and often a 'dry tap' on marrow aspirate, rather than the markedly raised WCC with a full granulocytic maturation spectrum described here.$x$, 5),
('ca000000-0000-0000-0000-000000000035', 'A', 'Bone marrow trephine biopsy as the first-line test', false, 'Ruled out because a simple erythropoietin level, along with clinical assessment and oxygen saturation, is the appropriate first-line discriminating test; marrow biopsy is not required as an initial investigation.', 1),
('ca000000-0000-0000-0000-000000000035', 'B', 'Direct antiglobulin test', false, 'Ruled out because this tests for immune-mediated haemolysis, which is not relevant to distinguishing primary from secondary polycythaemia.', 2),
('ca000000-0000-0000-0000-000000000035', 'C', 'Serum ferritin', false, 'Ruled out because this is used to assess iron status, not to distinguish the cause of polycythaemia.', 3),
('ca000000-0000-0000-0000-000000000035', 'D', 'Coagulation screen (PT/APTT)', false, 'Ruled out because this assesses clotting factor function, not the underlying cause of a raised haemoglobin.', 4),
('ca000000-0000-0000-0000-000000000035', 'E', 'Serum erythropoietin level', true, 'Correct. Distinguishing primary (myeloproliferative, e.g. polycythaemia vera, with low/suppressed erythropoietin) from secondary polycythaemia (driven by chronic hypoxia, with raised erythropoietin) is best done by measuring the erythropoietin level, alongside clinical context; a raised level here would support a secondary, hypoxia-driven cause.', 5),
('ca000000-0000-0000-0000-000000000036', 'A', 'Repeat liver function tests only, with no further investigation', false, 'Ruled out because unexplained hepatic vein thrombosis warrants investigation for an underlying prothrombotic cause, including an occult myeloproliferative neoplasm, rather than simply monitoring liver function.', 1),
('ca000000-0000-0000-0000-000000000036', 'B', 'JAK2 V617F mutation testing', true, 'Correct. Unexplained thrombosis at an unusual site (such as the hepatic veins causing Budd-Chiari syndrome), especially with subtly raised blood counts, should prompt screening for an underlying myeloproliferative neoplasm, most commonly tested for by JAK2 V617F mutation analysis.', 2),
('ca000000-0000-0000-0000-000000000036', 'C', 'Antiphospholipid antibody testing as the only investigation required', false, 'Ruled out because, while antiphospholipid syndrome is also a recognised cause of unusual-site thrombosis, the combination of thrombosis with even mildly raised blood counts should specifically also prompt JAK2 testing for an occult myeloproliferative neoplasm; it is not the single test that would be prioritised alone.', 3),
('ca000000-0000-0000-0000-000000000036', 'D', 'CT chest to look for occult lung malignancy as the first investigation', false, 'Ruled out because, while malignancy is a differential for unusual thrombosis, the raised blood counts here point more directly towards an occult myeloproliferative neoplasm, best screened for with JAK2 testing.', 4),
('ca000000-0000-0000-0000-000000000036', 'E', 'Reassure and no further investigation, as the thrombosis has already been identified and can be treated with anticoagulation alone', false, 'Ruled out because identifying an underlying cause (such as an occult MPN) is important for guiding both anticoagulation duration and cytoreductive/haematological management.', 5),
('ca000000-0000-0000-0000-000000000037', 'A', 'Immediate cytoreductive chemotherapy for all newly diagnosed patients regardless of risk', false, 'Ruled out because cytoreductive therapy is generally reserved for higher-risk patients (e.g. older age, prior thrombosis, very high counts), not offered universally as first-line treatment.', 1),
('ca000000-0000-0000-0000-000000000037', 'B', 'Warfarin anticoagulation as first-line therapy', false, 'Ruled out because warfarin is not first-line management for uncomplicated PV without a specific indication such as an established thrombotic event requiring anticoagulation; venesection and aspirin are the mainstay.', 2),
('ca000000-0000-0000-0000-000000000037', 'C', 'Regular blood transfusion to boost haemoglobin further', false, 'Ruled out because this would worsen the underlying problem (raised haematocrit/thrombotic risk) rather than treat it; venesection removes blood to reduce haematocrit, the opposite of transfusion.', 3),
('ca000000-0000-0000-0000-000000000037', 'D', 'Venesection to a target haematocrit, together with low-dose aspirin', true, 'Correct. Venesection is the first-line treatment to reduce haematocrit and thrombotic risk in polycythaemia vera, combined with low-dose aspirin to further reduce thrombotic risk, in patients without high-risk features requiring cytoreductive therapy.', 4),
('ca000000-0000-0000-0000-000000000037', 'E', 'No treatment required, only monitoring', false, 'Ruled out because untreated PV carries a significant thrombotic risk; venesection and aspirin are indicated to reduce this risk.', 5),
('ca000000-0000-0000-0000-000000000038', 'A', 'A new, unrelated diagnosis of iron deficiency anaemia', false, 'Ruled out because the blood film findings (teardrop cells, leucoerythroblastic picture) and progressive splenomegaly are specific for marrow fibrosis, not simple iron deficiency.', 1),
('ca000000-0000-0000-0000-000000000038', 'B', 'Well-controlled polycythaemia vera requiring no further action', false, 'Ruled out because this represents a significant clinical change (falling Hb, growing spleen, new blood film abnormalities) that requires prompt reassessment, not simple reassurance.', 2),
('ca000000-0000-0000-0000-000000000038', 'C', 'Acute viral infection causing transient bone marrow suppression', false, 'Ruled out because the chronic, progressive nature of the changes does not fit a transient viral illness.', 3),
('ca000000-0000-0000-0000-000000000038', 'D', 'Iatrogenic over-venesection causing anaemia', false, 'Ruled out because the vignette specifically states no recent venesection has occurred, and the blood film findings point to marrow fibrosis rather than simple depletion from phlebotomy.', 4),
('ca000000-0000-0000-0000-000000000038', 'E', 'Transformation of her polycythaemia vera into secondary (post-PV) myelofibrosis', true, 'Correct. A long-standing history of PV followed by falling haemoglobin (no longer requiring venesection), progressive splenomegaly, and a leucoerythroblastic blood film with teardrop cells indicates transformation of PV into secondary myelofibrosis, a recognised late complication of myeloproliferative neoplasms.', 5),
('ca000000-0000-0000-0000-000000000039', 'A', 'Essential thrombocythaemia', false, 'Ruled out because the clear, recent precipitant (splenectomy) provides an adequate explanation for a reactive thrombocytosis, making a primary myeloproliferative process far less likely without further evidence.', 1),
('ca000000-0000-0000-0000-000000000039', 'B', 'Polycythaemia vera', false, 'Ruled out because Hb is normal here, and the clinical context (recent splenectomy) points to a reactive, not autonomous, process.', 2),
('ca000000-0000-0000-0000-000000000039', 'C', 'Reactive thrombocytosis secondary to splenectomy', true, 'Correct. The spleen normally sequesters a significant proportion of circulating platelets, so splenectomy commonly causes a reactive rise in platelet count in the following weeks; this is usually transient and does not indicate a primary myeloproliferative disorder.', 3),
('ca000000-0000-0000-0000-000000000039', 'D', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes a low, not high, platelet count.', 4),
('ca000000-0000-0000-0000-000000000039', 'E', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC characteristically causes thrombocytopenia (from platelet consumption), not thrombocytosis, and there is no evidence of an acute critical illness driving a consumptive coagulopathy here.', 5),
('ca000000-0000-0000-0000-000000000040', 'A', 'Urgent venesection to reduce haematocrit and hyperviscosity-related symptoms', true, 'Correct. Symptoms of hyperviscosity (headache, visual disturbance, light-headedness) with a markedly raised haematocrit in known PV indicate an urgent need for venesection to reduce blood viscosity and associated thrombotic/ischaemic risk.', 1),
('ca000000-0000-0000-0000-000000000040', 'B', 'Reassure and arrange routine venesection in 2 weeks', false, 'Ruled out because symptomatic hyperviscosity requires urgent, not delayed, treatment given the risk of thrombotic or ischaemic complications (e.g. stroke).', 2),
('ca000000-0000-0000-0000-000000000040', 'C', 'Blood transfusion to improve his symptoms', false, 'Ruled out because transfusion would raise, not lower, his haematocrit, worsening hyperviscosity; venesection is required instead.', 3),
('ca000000-0000-0000-0000-000000000040', 'D', 'Start high-dose oral corticosteroids', false, 'Ruled out because corticosteroids do not address the underlying hyperviscosity; venesection is the appropriate treatment.', 4),
('ca000000-0000-0000-0000-000000000040', 'E', 'No treatment needed, as symptoms will resolve spontaneously', false, 'Ruled out because untreated hyperviscosity carries a significant risk of thrombotic and ischaemic complications, including stroke, and requires urgent treatment.', 5),
('ca000000-0000-0000-0000-000000000041', 'A', 'Delay all transfusion until full crossmatch results are available', false, 'Ruled out because this delay in a haemodynamically unstable patient with life-threatening haemorrhage risks death from exsanguination; emergency blood must be given immediately.', 1),
('ca000000-0000-0000-0000-000000000041', 'B', 'Give emergency group O, RhD-negative red cells immediately while crossmatched blood is being prepared', true, 'Correct. In life-threatening haemorrhage where there is no time to wait for full group and save/crossmatch, group O RhD-negative red cells are given immediately as a universal donor product, particularly important for women of childbearing potential to avoid RhD sensitisation, while type-specific or fully crossmatched blood is being prepared in parallel.', 2),
('ca000000-0000-0000-0000-000000000041', 'C', 'Give group AB, RhD-positive red cells as the universal emergency choice', false, 'Ruled out because group O (not AB) red cells are the universal red cell donor type; AB is the universal plasma donor type, a common point of confusion.', 3),
('ca000000-0000-0000-0000-000000000041', 'D', 'Give crystalloid fluid boluses only, with no blood products', false, 'Ruled out because large volumes of crystalloid alone in major haemorrhage dilute clotting factors and platelets and do not replace oxygen-carrying capacity; blood products are required.', 4),
('ca000000-0000-0000-0000-000000000041', 'E', $x$Wait for the patient's own previous blood group records from other hospitals before transfusing$x$, false, 'Ruled out because this delay is inappropriate in an immediately life-threatening emergency; emergency O RhD-negative blood should be given without delay.', 5),
('ca000000-0000-0000-0000-000000000042', 'A', 'Slow the transfusion rate and continue, reassessing in 30 minutes', false, 'Ruled out because continuing a transfusion causing a suspected haemolytic reaction risks worsening haemolysis, renal injury, and cardiovascular collapse; the transfusion must be stopped, not merely slowed.', 1),
('ca000000-0000-0000-0000-000000000042', 'B', 'Give antihistamines and continue the transfusion at the same rate', false, 'Ruled out because these features (fever, loin pain, haemoglobinuria, hypotension) suggest a haemolytic reaction, not a simple allergic reaction, and continuing transfusion is dangerous.', 2),
('ca000000-0000-0000-0000-000000000042', 'C', 'Reassure the patient that this is a normal transfusion reaction and no action is needed', false, 'Ruled out because this presentation is a medical emergency requiring immediate cessation of transfusion and urgent management, not reassurance.', 3),
('ca000000-0000-0000-0000-000000000042', 'D', 'Stop the transfusion immediately, maintain IV access, and provide supportive care while investigating for a haemolytic transfusion reaction', true, 'Correct. Fever, loin pain, dark urine (haemoglobinuria), and hypotension occurring shortly after starting a transfusion are classic features of an acute haemolytic transfusion reaction, usually due to ABO incompatibility; the transfusion must be stopped immediately, IV access maintained for fluids, and the reaction investigated and reported urgently.', 4),
('ca000000-0000-0000-0000-000000000042', 'E', 'Increase the transfusion rate to complete it quickly', false, 'Ruled out because this would worsen the reaction; the transfusion must be stopped immediately.', 5),
('ca000000-0000-0000-0000-000000000043', 'A', 'Transfusion-related acute lung injury (TRALI)', false, 'Ruled out because TRALI typically presents with hypotension (not hypertension) and a normal or low JVP, reflecting non-cardiogenic pulmonary oedema from donor antibody-mediated neutrophil activation, unlike the hypertensive, raised-JVP picture described here.', 1),
('ca000000-0000-0000-0000-000000000043', 'B', 'Acute haemolytic transfusion reaction', false, 'Ruled out because there is no fever, haemoglobinuria, or loin pain described; the presentation here is one of fluid overload rather than haemolysis.', 2),
('ca000000-0000-0000-0000-000000000043', 'C', 'Transfusion-associated circulatory overload (TACO)', true, 'Correct. Acute pulmonary oedema with hypertension and a raised JVP within hours of transfusion, particularly in a patient with pre-existing heart failure, is characteristic of TACO, caused by excessive volume/rate of transfusion overwhelming cardiac reserve.', 3),
('ca000000-0000-0000-0000-000000000043', 'D', 'Anaphylactic transfusion reaction', false, 'Ruled out because there is no urticaria, angioedema, or wheeze described; the clinical picture (pulmonary oedema with hypertension and raised JVP) fits volume overload rather than anaphylaxis.', 4),
('ca000000-0000-0000-0000-000000000043', 'E', 'Febrile non-haemolytic transfusion reaction', false, 'Ruled out because this typically causes mild fever and chills without pulmonary oedema or haemodynamic compromise, unlike the significant respiratory and cardiovascular findings here.', 5),
('ca000000-0000-0000-0000-000000000044', 'A', 'Transfusion-related acute lung injury (TRALI)', true, 'Correct. Acute hypoxia and bilateral pulmonary infiltrates developing within 6 hours of transfusion, with hypotension and no evidence of fluid overload (JVP not raised, no excessive fluid given), is characteristic of TRALI, thought to result from donor antibodies causing neutrophil-mediated lung injury.', 1),
('ca000000-0000-0000-0000-000000000044', 'B', 'Transfusion-associated circulatory overload (TACO)', false, 'Ruled out because TACO is characterised by signs of fluid overload (raised JVP, hypertension), which are specifically absent here; hypotension and a normal JVP point instead to TRALI.', 2),
('ca000000-0000-0000-0000-000000000044', 'C', 'Anaphylactic transfusion reaction', false, 'Ruled out because there is no urticaria, angioedema, or wheeze described; the presentation is of acute lung injury rather than a classic anaphylactic reaction.', 3),
('ca000000-0000-0000-0000-000000000044', 'D', 'Bacterial contamination of the blood product', false, 'Ruled out because, while this can cause severe reactions, the clinical picture described fits the classic definition of TRALI more precisely.', 4),
('ca000000-0000-0000-0000-000000000044', 'E', 'Acute haemolytic transfusion reaction', false, 'Ruled out because there is no fever, haemoglobinuria, or loin pain described; the primary problem here is acute lung injury/hypoxia, not haemolysis.', 5),
('ca000000-0000-0000-0000-000000000045', 'A', 'Continue the transfusion at the same rate with no intervention', false, 'Ruled out because any new fever during a transfusion needs to be assessed to exclude a more serious reaction before simply continuing at the same rate.', 1),
('ca000000-0000-0000-0000-000000000045', 'B', 'Stop the transfusion permanently and give broad-spectrum IV antibiotics immediately as the primary action', false, 'Ruled out because, although bacterial contamination is a differential to consider, the mild, isolated fever without hypotension or other systemic features described here is far more consistent with a benign febrile non-haemolytic reaction, and can often be managed with slowing/antipyretics after assessment, rather than automatically escalating to antibiotics as the primary first action.', 2),
('ca000000-0000-0000-0000-000000000045', 'C', 'Administer intramuscular adrenaline', false, 'Ruled out because there is no evidence of an anaphylactic reaction (no urticaria, angioedema, wheeze, hypotension); adrenaline is not indicated for a simple febrile reaction.', 3),
('ca000000-0000-0000-0000-000000000045', 'D', 'Increase the transfusion rate to complete it before further deterioration', false, 'Ruled out because increasing the rate during an evolving reaction is inappropriate; the transfusion should be paused/slowed while the reaction is assessed.', 4),
('ca000000-0000-0000-0000-000000000045', 'E', 'Stop or slow the transfusion, give an antipyretic, and monitor closely, excluding a more serious reaction', true, 'Correct. A mild, isolated temperature rise without haemodynamic compromise, respiratory symptoms, rash, or loin pain is most consistent with a febrile non-haemolytic transfusion reaction, caused by cytokines/antibodies reacting with residual white cells in the product; management is to stop or slow the transfusion temporarily, give an antipyretic, and monitor closely, while still excluding more serious reactions as a safety-net.', 5),
('ca000000-0000-0000-0000-000000000046', 'A', 'Slow the transfusion rate and give oral antihistamines', false, 'Ruled out because anaphylaxis with hypotension and wheeze requires immediate cessation of the transfusion and intramuscular adrenaline, not simply slowing the rate with oral treatment.', 1),
('ca000000-0000-0000-0000-000000000046', 'B', 'Continue the transfusion but give intravenous hydrocortisone alongside it', false, 'Ruled out because the transfusion causing the anaphylactic reaction must be stopped immediately; continuing it while treating the reaction is inappropriate and dangerous.', 2),
('ca000000-0000-0000-0000-000000000046', 'C', 'Stop the transfusion immediately and give intramuscular adrenaline, following the anaphylaxis protocol', true, 'Correct. Rapid onset of angioedema, urticaria, wheeze, and hypotension during transfusion is anaphylaxis, a medical emergency; the transfusion must be stopped immediately and intramuscular adrenaline given without delay, alongside standard anaphylaxis management.', 3),
('ca000000-0000-0000-0000-000000000046', 'D', 'Reassure the patient that this is a normal mild allergic reaction and continue observation only', false, 'Ruled out because this presentation, with airway/breathing/circulation compromise, is anaphylaxis and requires immediate emergency treatment, not simple observation.', 4),
('ca000000-0000-0000-0000-000000000046', 'E', 'Give oral chlorphenamine only, with no other intervention', false, 'Ruled out because oral antihistamines alone are inadequate for anaphylaxis with hypotension and wheeze; intramuscular adrenaline is required as first-line treatment.', 5),
('ca000000-0000-0000-0000-000000000047', 'A', 'Red cells alone, with plasma and platelets only once laboratory results become available', false, 'Ruled out because waiting for laboratory results before giving plasma and platelets risks significant dilutional coagulopathy during massive haemorrhage; early empirical fixed-ratio transfusion is recommended.', 1),
('ca000000-0000-0000-0000-000000000047', 'B', 'Crystalloid fluid alone in large volumes, avoiding blood products until haemoglobin is confirmed to be low', false, 'Ruled out because large-volume crystalloid resuscitation in major haemorrhage worsens dilutional coagulopathy and does not restore oxygen-carrying capacity; blood products are required early.', 2),
('ca000000-0000-0000-0000-000000000047', 'C', 'Cryoprecipitate alone, without fresh frozen plasma or platelets', false, 'Ruled out because cryoprecipitate alone does not provide the full range of clotting factors and platelets needed in early massive haemorrhage resuscitation; it is used as an adjunct, not as the sole product.', 3),
('ca000000-0000-0000-0000-000000000047', 'D', 'Red cells and albumin solution, with no fresh frozen plasma or platelets', false, 'Ruled out because albumin does not provide clotting factors or platelets; fresh frozen plasma and platelets are required alongside red cells in major haemorrhage protocols.', 4),
('ca000000-0000-0000-0000-000000000047', 'E', 'Fresh frozen plasma and platelets, given in a fixed ratio alongside red cells', true, 'Correct. The standard major haemorrhage protocol recommends early empirical transfusion of red cells, fresh frozen plasma, and platelets together in a fixed ratio (rather than red cells alone), to avoid dilutional coagulopathy and thrombocytopenia during massive resuscitation, with further product ratios subsequently guided by laboratory results and clinical response.', 5),
('ca000000-0000-0000-0000-000000000048', 'A', $x$Transfuse red cells to achieve a haemoglobin significantly above what a restrictive strategy would target, aiming for a much higher 'buffer' level$x$, false, 'Ruled out because liberal transfusion to a higher-than-necessary threshold is not supported by evidence and exposes the patient to unnecessary transfusion risks without added benefit in a stable patient.', 1),
('ca000000-0000-0000-0000-000000000048', 'B', 'Do not transfuse at all regardless of symptoms or further bleeding, since he is currently asymptomatic', false, $x$Ruled out because, while restrictive thresholds avoid unnecessary transfusion, a sufficiently low haemoglobin with ongoing risk still warrants transfusion; the point of a restrictive strategy is a lower but still defined threshold, not 'never transfuse.'$x$, 2),
('ca000000-0000-0000-0000-000000000048', 'C', 'Base the transfusion decision solely on his coronary artery disease history, transfusing regardless of his current haemoglobin level', false, $x$Ruled out because transfusion decisions should be based on the patient's haemoglobin level and clinical status, not on comorbidity history alone.$x$, 3),
('ca000000-0000-0000-0000-000000000048', 'D', 'Transfuse red cells to bring his haemoglobin above the standard restrictive transfusion threshold, then reassess clinically rather than transfusing to a higher target', true, 'Correct. Current UK guidance recommends a restrictive transfusion strategy for most stable patients, transfusing to bring the haemoglobin above a defined lower threshold (rather than to a higher, liberal target), then clinically reassessing, since restrictive strategies have been shown to be at least as safe as liberal transfusion in most stable patients, including many with stable cardiovascular disease.', 4),
('ca000000-0000-0000-0000-000000000048', 'E', 'Transfuse only if he becomes symptomatic, with no defined haemoglobin threshold guiding the decision', false, 'Ruled out because restrictive transfusion strategies do use a defined haemoglobin threshold (rather than symptoms alone) to guide the transfusion decision in stable patients.', 5),
('ca000000-0000-0000-0000-000000000049', 'A', 'Washed blood products only, with no irradiation required', false, 'Ruled out because washing removes plasma proteins (useful in IgA deficiency or recurrent allergic reactions) but does not inactivate donor lymphocytes; irradiation is specifically required to prevent transfusion-associated graft-versus-host disease in severely immunocompromised patients.', 1),
('ca000000-0000-0000-0000-000000000049', 'B', 'Irradiated blood products', true, 'Correct. Severely immunocompromised patients (such as those with severe combined immunodeficiency, or undergoing/having had stem cell transplantation) are at risk of transfusion-associated graft-versus-host disease from viable donor lymphocytes in standard blood products; irradiation inactivates these lymphocytes and is essential in this group.', 2),
('ca000000-0000-0000-0000-000000000049', 'C', 'CMV-seropositive blood products preferentially', false, 'Ruled out because immunocompromised patients require CMV-seronegative (or leucodepleted, per local policy) products to reduce transmission risk, not seropositive products.', 3),
('ca000000-0000-0000-0000-000000000049', 'D', 'No special requirements beyond standard leucodepletion', false, 'Ruled out because standard leucodepletion alone does not reliably prevent transfusion-associated graft-versus-host disease; irradiation is specifically required in this high-risk group.', 4),
('ca000000-0000-0000-0000-000000000049', 'E', 'Fresh, non-leucodepleted whole blood', false, 'Ruled out because non-leucodepleted products increase (not decrease) the risk of transfusion transmitted infection and immune complications; UK blood products are universally leucodepleted, and irradiation is additionally required here.', 5),
('ca000000-0000-0000-0000-000000000050', 'A', 'Routine antenatal anti-D immunoglobulin prophylaxis', true, 'Correct. RhD-negative women who are not already sensitised (no anti-D antibodies detected) should receive routine antenatal anti-D immunoglobulin prophylaxis (in addition to after any sensitising events and after delivery if the baby is RhD-positive), to prevent maternal sensitisation to fetal RhD-positive red cells and reduce the risk of haemolytic disease of the newborn.', 1),
('ca000000-0000-0000-0000-000000000050', 'B', 'No anti-D immunoglobulin required, as no sensitising event has occurred', false, 'Ruled out because routine antenatal anti-D prophylaxis is given even in the absence of a known sensitising event, since small numbers of fetal red cells can cross the placenta silently during pregnancy.', 2),
('ca000000-0000-0000-0000-000000000050', 'C', 'Anti-D immunoglobulin only if the baby is confirmed RhD-negative at birth', false, $x$Ruled out because antenatal prophylaxis is given based on the mother's RhD-negative status during pregnancy, before the baby's blood group is known; postnatal anti-D is given if the baby is confirmed RhD-positive.$x$, 3),
('ca000000-0000-0000-0000-000000000050', 'D', 'Immediate exchange transfusion for the mother', false, 'Ruled out because exchange transfusion is not part of routine anti-D sensitisation prevention; anti-D immunoglobulin prophylaxis is the appropriate intervention.', 4),
('ca000000-0000-0000-0000-000000000050', 'E', 'Full red cell transfusion for the mother to boost her RhD-positive antibody response', false, 'Ruled out because deliberately inducing sensitisation is the opposite of the goal, which is to prevent maternal anti-D antibody formation.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('ca000000-0000-0000-0000-000000000001', 'Iron deficiency anaemia in a man or postmenopausal woman is assumed to be due to occult GI blood loss until proven otherwise and warrants bidirectional (upper and lower) endoscopy.', 1),
('ca000000-0000-0000-0000-000000000001', 'Low ferritin is the most specific marker of iron deficiency, though it can be falsely normal/raised in inflammation as an acute phase protein.', 2),
('ca000000-0000-0000-0000-000000000001', 'Coeliac disease is also tested for as a treatable cause of iron malabsorption, but does not replace endoscopic investigation for malignancy.', 3),
('ca000000-0000-0000-0000-000000000002', 'B12 deficiency must always be corrected before (or alongside, never after) folic acid, since giving folate alone in B12 deficiency can precipitate or worsen subacute combined degeneration of the spinal cord.', 1),
('ca000000-0000-0000-0000-000000000002', 'Neurological features (peripheral neuropathy, subacute combined degeneration) can occur in B12 deficiency without severe anaemia.', 2),
('ca000000-0000-0000-0000-000000000002', 'Autoimmune conditions (thyroid disease, vitiligo) cluster with pernicious anaemia due to autoimmune destruction of gastric parietal cells.', 3),
('ca000000-0000-0000-0000-000000000003', 'Folate deficiency causes macrocytic anaemia; hypersegmented neutrophils can occur in either B12 or folate deficiency but are classically emphasised with B12 deficiency.', 1),
('ca000000-0000-0000-0000-000000000003', 'Untreated maternal folate deficiency in pregnancy increases the risk of neural tube defects.', 2),
('ca000000-0000-0000-0000-000000000003', 'Malabsorptive conditions such as coeliac disease are an important treatable cause of folate deficiency and should be actively managed.', 3),
('ca000000-0000-0000-0000-000000000004', 'Anaemia of chronic disease classically shows low serum iron, low TIBC, and normal or raised ferritin, contrasting with true iron deficiency (low iron, high TIBC, low ferritin).', 1),
('ca000000-0000-0000-0000-000000000004', 'Ferritin is an acute-phase protein and can be falsely normal or elevated in inflammatory states even when true iron stores are depleted.', 2),
('ca000000-0000-0000-0000-000000000004', 'Chronic inflammatory conditions (rheumatoid arthritis, chronic kidney disease, malignancy) are common causes of anaemia of chronic disease.', 3),
('ca000000-0000-0000-0000-000000000005', 'A positive direct antiglobulin (Coombs) test distinguishes immune-mediated haemolysis from hereditary/enzymatic causes.', 1),
('ca000000-0000-0000-0000-000000000005', 'Raised bilirubin, raised LDH, low haptoglobin, and reticulocytosis together indicate active haemolysis.', 2),
('ca000000-0000-0000-0000-000000000005', 'Warm AIHA is often secondary to autoimmune disease (e.g. SLE), lymphoproliferative disorders, or certain drugs, and management includes corticosteroids.', 3),
('ca000000-0000-0000-0000-000000000006', 'G6PD deficiency is an X-linked enzyme deficiency that predisposes red cells to oxidative damage from certain drugs (e.g. nitrofurantoin, sulfonamides, primaquine), fava beans, and infection.', 1),
('ca000000-0000-0000-0000-000000000006', 'Heinz bodies and bite cells on blood film with a negative direct antiglobulin test suggest an enzymatic/oxidative cause of haemolysis rather than an immune one.', 2),
('ca000000-0000-0000-0000-000000000006', 'Precipitating oxidant drugs should be stopped and avoided in future in confirmed G6PD deficiency.', 3),
('ca000000-0000-0000-0000-000000000007', 'Vaso-occlusive (painful) crisis in sickle cell disease requires prompt, adequate analgesia; under-treating pain is a recognised and preventable harm.', 1),
('ca000000-0000-0000-0000-000000000007', 'Common precipitants of sickle crises include infection, dehydration, cold exposure, and hypoxia, and should be actively sought and treated.', 2),
('ca000000-0000-0000-0000-000000000007', 'Acute chest syndrome and stroke are life-threatening sickle complications that may require exchange transfusion; uncomplicated painful crisis does not.', 3),
('ca000000-0000-0000-0000-000000000008', 'A disproportionately low MCV relative to Hb, with a normal ferritin, in someone from a population with a high thalassaemia carrier rate, should prompt haemoglobinopathy screening rather than assuming iron deficiency.', 1),
('ca000000-0000-0000-0000-000000000008', 'Thalassaemia trait is usually asymptomatic and does not require treatment, but has important reproductive/genetic counselling implications.', 2),
('ca000000-0000-0000-0000-000000000008', 'Distinguishing thalassaemia trait from iron deficiency anaemia matters because iron supplementation is unhelpful (and potentially harmful) in thalassaemia trait.', 3),
('ca000000-0000-0000-0000-000000000009', 'In CKD and other chronic inflammatory states, ferritin can be falsely elevated despite true iron deficiency; transferrin saturation is a more reliable marker in this context.', 1),
('ca000000-0000-0000-0000-000000000009', 'Anaemia of CKD is multifactorial: reduced erythropoietin production plus iron-restricted erythropoiesis from inflammation (raised hepcidin).', 2),
('ca000000-0000-0000-0000-000000000009', 'Iron status should be assessed and optimised before or alongside erythropoiesis-stimulating agents in CKD anaemia.', 3),
('ca000000-0000-0000-0000-000000000010', 'A background of gastric surgery is a recognised risk factor for B12 deficiency due to loss of intrinsic factor-producing parietal cells.', 1),
('ca000000-0000-0000-0000-000000000010', 'Megaloblastic anaemia (macrocytosis with hypersegmented neutrophils) should prompt B12 and folate testing before treatment is started.', 2),
('ca000000-0000-0000-0000-000000000010', 'Empirical folate replacement without knowing B12 status risks precipitating or worsening neurological complications of undiagnosed B12 deficiency.', 3),
('ca000000-0000-0000-0000-000000000011', 'Haemophilia A and B are X-linked recessive disorders causing deep bleeding (haemarthrosis, muscle haematomas) with an isolated prolonged APTT and normal PT/platelet count.', 1),
('ca000000-0000-0000-0000-000000000011', 'A family history following an X-linked pattern (affected maternal male relatives) supports the diagnosis.', 2),
('ca000000-0000-0000-0000-000000000011', 'Recurrent haemarthrosis without treatment can lead to chronic joint damage (haemophilic arthropathy).', 3),
('ca000000-0000-0000-0000-000000000012', 'Von Willebrand disease is the most common inherited bleeding disorder and classically presents with mucocutaneous bleeding (epistaxis, menorrhagia, easy bruising, prolonged bleeding after dental/surgical procedures).', 1),
('ca000000-0000-0000-0000-000000000012', 'Von Willebrand factor stabilises factor VIII, so deficiency can mildly prolong the APTT while PT and platelet count remain normal.', 2),
('ca000000-0000-0000-0000-000000000012', 'Desmopressin (DDAVP) can be used to raise von Willebrand factor and factor VIII levels in mild disease, e.g. before minor procedures.', 3),
('ca000000-0000-0000-0000-000000000013', 'DIC is triggered by conditions such as sepsis, major trauma, obstetric complications, and malignancy, causing widespread activation and subsequent consumption of clotting factors and platelets.', 1),
('ca000000-0000-0000-0000-000000000013', 'Typical findings are thrombocytopenia, prolonged PT and APTT, low fibrinogen, and markedly raised D-dimer/fibrin degradation products.', 2),
('ca000000-0000-0000-0000-000000000013', 'Management focuses on treating the underlying trigger, with blood product support (platelets, FFP, cryoprecipitate) guided by bleeding and laboratory parameters.', 3),
('ca000000-0000-0000-0000-000000000014', 'Major or life-threatening bleeding on warfarin requires immediate reversal with IV vitamin K plus prothrombin complex concentrate, not FFP alone or watchful waiting.', 1),
('ca000000-0000-0000-0000-000000000014', 'Protamine sulfate is the reversal agent for heparin, not warfarin, a common point of confusion.', 2),
('ca000000-0000-0000-0000-000000000014', 'INR should be rechecked after reversal to confirm correction, alongside resuscitation and identifying/treating the bleeding source.', 3),
('ca000000-0000-0000-0000-000000000015', 'Childhood ITP classically follows a viral illness and causes isolated thrombocytopenia in an otherwise well child, often resolving spontaneously.', 1),
('ca000000-0000-0000-0000-000000000015', 'Presence of other cytopenias, organomegaly, lymphadenopathy, or blasts on blood film should prompt investigation for leukaemia rather than assuming ITP.', 2),
('ca000000-0000-0000-0000-000000000015', 'Most cases of childhood ITP are self-limiting; treatment is reserved for significant bleeding or very low platelet counts.', 3),
('ca000000-0000-0000-0000-000000000016', 'Vitamin K is required for synthesis of factors II, VII, IX, and X; deficiency prolongs both PT and APTT.', 1),
('ca000000-0000-0000-0000-000000000016', 'Prophylactic vitamin K at birth prevents vitamin K deficiency bleeding of the newborn; infants who miss this (e.g. home birth) or are exclusively breastfed are at higher risk.', 2),
('ca000000-0000-0000-0000-000000000016', 'Treatment is with intravenous or intramuscular vitamin K replacement.', 3),
('ca000000-0000-0000-0000-000000000017', 'TTP causes a microangiopathic haemolytic anaemia (schistocytes, raised LDH, negative DAT) with severe thrombocytopenia and a normal coagulation screen, distinguishing it from DIC (where PT/APTT/fibrinogen are deranged).', 1),
('ca000000-0000-0000-0000-000000000017', 'Neurological and renal involvement alongside thrombocytopenia and haemolysis should raise suspicion for TTP and prompt urgent haematology involvement.', 2),
('ca000000-0000-0000-0000-000000000017', 'Plasma exchange is the definitive emergency treatment; platelet transfusion is generally avoided as it may worsen microthrombosis.', 3),
('ca000000-0000-0000-0000-000000000018', 'Heparin-induced thrombocytopenia typically develops 5-10 days after heparin exposure and is characterised by a falling platelet count with new or worsening thrombosis, not primarily bleeding.', 1),
('ca000000-0000-0000-0000-000000000018', 'All heparin (including low molecular weight heparin and heparin flushes) must be stopped, and switched to a non-heparin anticoagulant, because the prothrombotic risk persists.', 2),
('ca000000-0000-0000-0000-000000000018', 'Platelet transfusion is generally avoided in HIT as it does not address the underlying antibody-mediated platelet activation and thrombotic risk.', 3),
('ca000000-0000-0000-0000-000000000019', 'Idarucizumab is the specific reversal agent for dabigatran; andexanet alfa is used for factor Xa inhibitors (e.g. apixaban, rivaroxaban).', 1),
('ca000000-0000-0000-0000-000000000019', 'Life-threatening bleeding (e.g. intracranial haemorrhage) on a DOAC requires urgent specific reversal where available, alongside standard resuscitation.', 2),
('ca000000-0000-0000-0000-000000000019', 'Protamine and vitamin K are not effective reversal agents for DOACs; confusing these reversal strategies is a common error.', 3),
('ca000000-0000-0000-0000-000000000020', 'Aspirin causes a qualitative platelet function defect (irreversible COX-1 inhibition) that is not reflected in standard platelet count, PT, or APTT results.', 1),
('ca000000-0000-0000-0000-000000000020', 'Antiplatelet-related bleeding tendencies should be considered even when routine coagulation screens are normal.', 2),
('ca000000-0000-0000-0000-000000000020', $x$Aspirin's antiplatelet effect lasts for the lifespan of the affected platelets (about 7-10 days), since the inhibition is irreversible.$x$, 3),
('ca000000-0000-0000-0000-000000000021', 'Red flags for childhood leukaemia include unexplained bruising/bleeding, pallor, bone pain, lymphadenopathy, hepatosplenomegaly, and persistent fever, and warrant urgent same-day specialist referral.', 1),
('ca000000-0000-0000-0000-000000000021', 'Circulating blast cells on a blood film in a child with cytopenias is highly suspicious for acute leukaemia and requires urgent bone marrow confirmation.', 2),
('ca000000-0000-0000-0000-000000000021', 'Corticosteroids should not be started before a definitive diagnosis, as they can mask or alter diagnostic findings in suspected leukaemia/lymphoma.', 3),
('ca000000-0000-0000-0000-000000000022', 'Acute promyelocytic leukaemia is a subtype of AML strongly associated with disseminated intravascular coagulation and is a haematological emergency requiring urgent specialist input.', 1),
('ca000000-0000-0000-0000-000000000022', 'Abnormal promyelocytes on blood film, combined with signs of DIC (bleeding, low fibrinogen, raised D-dimer, prolonged PT/APTT), should prompt urgent same-day haematology referral.', 2),
('ca000000-0000-0000-0000-000000000022', 'Early recognition and treatment markedly improves outcomes in APML, but delay in diagnosis is associated with high early mortality from bleeding.', 3),
('ca000000-0000-0000-0000-000000000023', 'CLL is often an incidental finding in asymptomatic older adults, characterised by a mature lymphocytosis with smudge cells on blood film.', 1),
('ca000000-0000-0000-0000-000000000023', $x$Many patients with CLL require no immediate treatment and are managed with a 'watch and wait' approach, since the disease can be indolent for years.$x$, 2),
('ca000000-0000-0000-0000-000000000023', 'Smudge cells (fragile lymphocytes damaged during film preparation) are a characteristic, though not entirely specific, feature of CLL.', 3),
('ca000000-0000-0000-0000-000000000024', 'Painless, rubbery lymphadenopathy with B symptoms (fever, night sweats, weight loss) in a young adult should raise suspicion for Hodgkin lymphoma.', 1),
('ca000000-0000-0000-0000-000000000024', 'Alcohol-induced lymph node pain, while classic, is present in only a minority of patients and is not required to make the diagnosis.', 2),
('ca000000-0000-0000-0000-000000000024', 'Excision lymph node biopsy (not fine needle aspiration) is required to assess architecture and identify Reed-Sternberg cells, confirming the diagnosis.', 3),
('ca000000-0000-0000-0000-000000000025', 'Diffuse large B-cell lymphoma is the most common subtype of non-Hodgkin lymphoma and typically presents with a rapidly enlarging nodal mass, often with B symptoms.', 1),
('ca000000-0000-0000-0000-000000000025', 'Histology distinguishes Hodgkin lymphoma (Reed-Sternberg cells) from non-Hodgkin lymphoma subtypes (e.g. sheets of large atypical B cells in DLBCL).', 2),
('ca000000-0000-0000-0000-000000000025', 'Staging (including imaging above and below the diaphragm) is required to guide treatment in lymphoma.', 3),
('ca000000-0000-0000-0000-000000000026', $x$The 'CRAB' features (hyperCalcaemia, Renal impairment, Anaemia, Bone lesions) alongside a monoclonal paraprotein are the classic diagnostic clues for multiple myeloma.$x$, 1),
('ca000000-0000-0000-0000-000000000026', 'Lytic bone lesions in myeloma result from osteoclast activation by malignant plasma cells, unlike the sclerotic lesions typical of prostate cancer metastases.', 2),
('ca000000-0000-0000-0000-000000000026', 'Renal impairment in myeloma can result from light chain deposition/cast nephropathy and should prompt urgent investigation and hydration while avoiding nephrotoxic agents.', 3),
('ca000000-0000-0000-0000-000000000027', 'Fever in a patient who is (or is likely to be) neutropenic following chemotherapy is neutropenic sepsis until proven otherwise and is a medical emergency.', 1),
('ca000000-0000-0000-0000-000000000027', 'Empirical broad-spectrum IV antibiotics should be started within 1 hour of presentation, after taking cultures, without waiting for results.', 2),
('ca000000-0000-0000-0000-000000000027', 'Any delay in treating neutropenic sepsis is associated with significantly increased mortality.', 3),
('ca000000-0000-0000-0000-000000000028', 'Tumour lysis syndrome classically causes hyperkalaemia, hyperphosphataemia, hypocalcaemia, and hyperuricaemia, typically within 24-72 hours of starting treatment for a high-grade, bulky tumour.', 1),
('ca000000-0000-0000-0000-000000000028', 'Patients at high risk (e.g. Burkitt lymphoma, high tumour burden, pre-existing renal impairment) should receive prophylactic measures (aggressive IV hydration and urate-lowering therapy) before starting chemotherapy.', 2),
('ca000000-0000-0000-0000-000000000028', 'Tumour lysis syndrome can cause life-threatening cardiac arrhythmias (from hyperkalaemia and hypocalcaemia) and acute kidney injury, requiring urgent monitoring and treatment.', 3),
('ca000000-0000-0000-0000-000000000029', 'Pallor, unexplained bruising, fatigue, and splenomegaly/hepatomegaly in a child are red flag features requiring urgent (same-day/48-hour) full blood count and immediate specialist referral if leukaemia is suspected.', 1),
('ca000000-0000-0000-0000-000000000029', 'Delay in recognising and referring suspected childhood leukaemia can worsen outcomes; urgent pathways exist specifically to avoid this.', 2),
('ca000000-0000-0000-0000-000000000029', 'Non-accidental injury should remain a differential for unexplained bruising, but should not delay urgent haematological work-up when other red flag features are present.', 3),
('ca000000-0000-0000-0000-000000000030', 'Superior vena cava obstruction presents with facial/neck swelling, dyspnoea, and distended neck and chest wall collateral veins, often worsened by lying flat.', 1),
('ca000000-0000-0000-0000-000000000030', 'In young adults, mediastinal lymphoma is an important and relatively common cause of SVC obstruction and should prompt urgent oncological work-up.', 2),
('ca000000-0000-0000-0000-000000000030', 'SVC obstruction is a genuine oncological emergency requiring rapid assessment, tissue diagnosis where possible, and urgent treatment planning.', 3),
('ca000000-0000-0000-0000-000000000031', 'Polycythaemia vera classically presents with aquagenic pruritus, erythromelalgia, headaches, and a plethoric complexion, with a low erythropoietin level distinguishing it from secondary (reactive) polycythaemia.', 1),
('ca000000-0000-0000-0000-000000000031', 'Most cases of PV are associated with a JAK2 V617F mutation.', 2),
('ca000000-0000-0000-0000-000000000031', 'Management includes venesection to reduce haematocrit and low-dose aspirin, with cytoreductive therapy in higher-risk patients, aiming to reduce thrombotic risk.', 3),
('ca000000-0000-0000-0000-000000000032', 'Essential thrombocythaemia should be considered when a markedly raised platelet count cannot be explained by a reactive cause (iron deficiency, infection, inflammation, malignancy, post-splenectomy).', 1),
('ca000000-0000-0000-0000-000000000032', 'Microvascular symptoms such as erythromelalgia and headache can occur due to platelet-mediated microvascular occlusion, even without a very high platelet count.', 2),
('ca000000-0000-0000-0000-000000000032', 'Management aims to reduce thrombotic and haemorrhagic risk, often with aspirin and cytoreductive therapy in higher-risk patients.', 3),
('ca000000-0000-0000-0000-000000000033', 'Massive splenomegaly with constitutional symptoms, teardrop red cells, and a leucoerythroblastic blood film picture are characteristic of primary myelofibrosis.', 1),
('ca000000-0000-0000-0000-000000000033', $x$A 'dry tap' on bone marrow aspiration reflects marrow fibrosis and typically requires a trephine biopsy to confirm the diagnosis.$x$, 2),
('ca000000-0000-0000-0000-000000000033', 'Primary myelofibrosis can arise de novo or as a progression from polycythaemia vera or essential thrombocythaemia.', 3),
('ca000000-0000-0000-0000-000000000034', 'CML classically presents with a markedly raised white cell count showing a full spectrum of maturing granulocytic cells, basophilia, and massive splenomegaly.', 1),
('ca000000-0000-0000-0000-000000000034', 'Most cases of CML are driven by the BCR-ABL1 fusion gene, resulting from the Philadelphia chromosome translocation t(9;22), confirmed on cytogenetic/molecular testing.', 2),
('ca000000-0000-0000-0000-000000000034', 'Tyrosine kinase inhibitors (targeting BCR-ABL) have transformed the prognosis of CML, but diagnosis first requires distinguishing it from a reactive leucocytosis and other myeloproliferative/leukaemic processes.', 3),
('ca000000-0000-0000-0000-000000000035', 'Erythropoietin level helps distinguish primary polycythaemia (e.g. PV, where EPO is typically low/suppressed) from secondary polycythaemia (e.g. chronic hypoxia from COPD, where EPO is appropriately raised).', 1),
('ca000000-0000-0000-0000-000000000035', 'Chronic hypoxic conditions (COPD, obstructive sleep apnoea, cyanotic congenital heart disease, high altitude) are recognised causes of secondary (reactive) polycythaemia.', 2),
('ca000000-0000-0000-0000-000000000035', 'Unlike PV, secondary polycythaemia does not typically cause a panmyelosis (raised WCC and platelets alongside the raised Hb).', 3),
('ca000000-0000-0000-0000-000000000036', 'Unusual-site venous thrombosis (e.g. hepatic, portal, splenic, or cerebral venous thrombosis), especially with subtly raised blood counts, should prompt screening for an underlying myeloproliferative neoplasm.', 1),
('ca000000-0000-0000-0000-000000000036', 'Budd-Chiari syndrome (hepatic vein thrombosis) is a recognised complication of occult polycythaemia vera or essential thrombocythaemia, even when blood counts are only mildly elevated.', 2),
('ca000000-0000-0000-0000-000000000036', 'JAK2 V617F mutation testing is the key initial screening test for an underlying myeloproliferative neoplasm in this context.', 3),
('ca000000-0000-0000-0000-000000000037', 'First-line management of PV is venesection to reduce haematocrit, combined with low-dose aspirin to reduce thrombotic risk.', 1),
('ca000000-0000-0000-0000-000000000037', 'Cytoreductive therapy (e.g. hydroxycarbamide) is reserved for higher-risk patients (older age, prior thrombosis, poorly controlled counts despite venesection).', 2),
('ca000000-0000-0000-0000-000000000037', 'The main morbidity and mortality risk in PV relates to thrombosis (arterial and venous), which drives the treatment approach.', 3),
('ca000000-0000-0000-0000-000000000038', 'Myeloproliferative neoplasms (PV, ET) can transform over time into secondary myelofibrosis, characterised by progressive cytopenias, worsening splenomegaly, and a leucoerythroblastic blood film with teardrop cells.', 1),
('ca000000-0000-0000-0000-000000000038', 'A previously stable myeloproliferative disorder that develops new cytopenias, an enlarging spleen, or constitutional symptoms should prompt reassessment for disease transformation.', 2),
('ca000000-0000-0000-0000-000000000038', 'Recognising this transformation is important as it changes prognosis and management, and warrants specialist haematology reassessment.', 3),
('ca000000-0000-0000-0000-000000000039', 'Splenectomy is a recognised cause of reactive thrombocytosis, since the spleen normally sequesters a proportion of circulating platelets.', 1),
('ca000000-0000-0000-0000-000000000039', 'Reactive thrombocytosis (from splenectomy, iron deficiency, infection, inflammation, or malignancy) should be distinguished from a primary myeloproliferative neoplasm such as essential thrombocythaemia, particularly when there is a clear precipitating cause.', 2),
('ca000000-0000-0000-0000-000000000039', 'A sustained thrombocytosis without an adequate reactive explanation warrants further investigation (e.g. JAK2 testing) for a primary myeloproliferative process.', 3),
('ca000000-0000-0000-0000-000000000040', 'Symptoms of hyperviscosity in PV (headache, visual disturbance, light-headedness, erythromelalgia) with a markedly raised haematocrit require urgent venesection.', 1),
('ca000000-0000-0000-0000-000000000040', 'Missed or inadequate venesection is a common cause of poorly controlled PV presenting with recurrence of hyperviscosity symptoms.', 2),
('ca000000-0000-0000-0000-000000000040', 'Hyperviscosity in poorly controlled PV carries a significant risk of thrombotic and ischaemic complications, including stroke and myocardial infarction.', 3),
('ca000000-0000-0000-0000-000000000041', 'Group O RhD-negative red cells are the universal emergency red cell choice when there is no time for group and save/crossmatch, particularly important for females of childbearing potential.', 1),
('ca000000-0000-0000-0000-000000000041', 'Group AB is the universal plasma donor group, not group O, a common source of confusion with red cell universal donor status.', 2),
('ca000000-0000-0000-0000-000000000041', 'Emergency blood should never be withheld from a haemodynamically unstable, actively bleeding patient while awaiting formal crossmatch.', 3),
('ca000000-0000-0000-0000-000000000042', 'Fever, loin/back pain, hypotension, and haemoglobinuria shortly after starting a transfusion suggest acute haemolytic transfusion reaction, most commonly due to ABO incompatibility from clerical/identification error.', 1),
('ca000000-0000-0000-0000-000000000042', 'The immediate action for any suspected serious transfusion reaction is to stop the transfusion, maintain IV access, and provide supportive care while investigating.', 2),
('ca000000-0000-0000-0000-000000000042', 'Acute haemolytic transfusion reactions can progress to acute kidney injury and disseminated intravascular coagulation if not recognised and managed promptly.', 3),
('ca000000-0000-0000-0000-000000000043', 'TACO presents with signs of fluid overload (hypertension, raised JVP, pulmonary oedema), typically in patients with reduced cardiac reserve, and is related to transfusion volume/rate.', 1),
('ca000000-0000-0000-0000-000000000043', 'TRALI, by contrast, presents with hypotension and non-cardiogenic pulmonary oedema (normal/low JVP), occurring within 6 hours of transfusion, due to donor antibody-mediated neutrophil activation in the lungs.', 2),
('ca000000-0000-0000-0000-000000000043', 'Distinguishing TACO from TRALI is important because management differs: TACO responds to diuretics and slowing/stopping the transfusion, whereas TRALI is managed with supportive respiratory care.', 3),
('ca000000-0000-0000-0000-000000000044', 'TRALI presents with acute hypoxia and bilateral pulmonary infiltrates within 6 hours of transfusion, with hypotension and no evidence of fluid overload, distinguishing it from TACO.', 1),
('ca000000-0000-0000-0000-000000000044', $x$TRALI is thought to result from donor plasma antibodies causing activation and sequestration of the recipient's neutrophils in the pulmonary microvasculature.$x$, 2),
('ca000000-0000-0000-0000-000000000044', 'Management of TRALI is supportive (oxygen, respiratory support as needed), with the transfusion stopped and the reaction reported to the blood transfusion service.', 3),
('ca000000-0000-0000-0000-000000000045', 'Febrile non-haemolytic transfusion reactions cause a mild, isolated temperature rise and chills without haemodynamic compromise, and are usually managed by stopping/slowing the transfusion and giving antipyretics.', 1),
('ca000000-0000-0000-0000-000000000045', 'Any new fever during a transfusion should still prompt assessment to exclude more serious reactions (haemolytic reaction, bacterial contamination) before assuming a benign cause.', 2),
('ca000000-0000-0000-0000-000000000045', 'Febrile non-haemolytic reactions are thought to result from cytokines and antibodies reacting with residual leucocytes in the transfused product.', 3),
('ca000000-0000-0000-0000-000000000046', 'Anaphylactic transfusion reactions typically occur rapidly and can be more common/severe in patients with selective IgA deficiency who have anti-IgA antibodies, reacting to IgA in donor plasma.', 1),
('ca000000-0000-0000-0000-000000000046', 'Anaphylaxis during transfusion requires immediate cessation of the transfusion and intramuscular adrenaline, following standard anaphylaxis management.', 2),
('ca000000-0000-0000-0000-000000000046', 'Patients with a history of severe transfusion reactions related to IgA deficiency may need specially prepared (IgA-depleted or washed) blood products for future transfusions.', 3),
('ca000000-0000-0000-0000-000000000047', $x$Major haemorrhage protocols recommend early, empirical transfusion of red cells, fresh frozen plasma, and platelets together in a fixed ratio, rather than red cells alone or a 'wait for labs' approach.$x$, 1),
('ca000000-0000-0000-0000-000000000047', 'Large-volume crystalloid resuscitation in major trauma haemorrhage worsens dilutional coagulopathy and should be minimised in favour of early blood product transfusion.', 2),
('ca000000-0000-0000-0000-000000000047', 'Cryoprecipitate may be added if fibrinogen remains low despite fixed-ratio product transfusion, guided by repeat laboratory testing.', 3),
('ca000000-0000-0000-0000-000000000048', 'Restrictive transfusion strategies (transfusing to a lower but defined haemoglobin threshold, then reassessing) are now standard practice for most stable patients, including many with stable cardiovascular disease, and are supported by trial evidence over liberal strategies.', 1),
('ca000000-0000-0000-0000-000000000048', $x$Transfusion decisions should be guided by the patient's haemoglobin level and overall clinical picture, not by comorbidity alone or symptoms in isolation.$x$, 2),
('ca000000-0000-0000-0000-000000000048', 'Over-transfusion carries its own risks (circulatory overload, transfusion reactions, unnecessary donor exposure) and should be avoided when not clinically indicated.', 3),
('ca000000-0000-0000-0000-000000000049', 'Irradiated blood products are required for severely immunocompromised patients (e.g. SCID, post/pre-stem cell transplant, certain haematological malignancies) to prevent transfusion-associated graft-versus-host disease.', 1),
('ca000000-0000-0000-0000-000000000049', 'Washed blood products remove plasma proteins and are used for patients with IgA deficiency or recurrent severe allergic transfusion reactions, but do not prevent graft-versus-host disease.', 2),
('ca000000-0000-0000-0000-000000000049', 'Failure to use irradiated products in at-risk patients can result in transfusion-associated graft-versus-host disease, which has a very high mortality.', 3),
('ca000000-0000-0000-0000-000000000050', 'RhD-negative women without existing anti-D antibodies should receive routine antenatal anti-D immunoglobulin prophylaxis, in addition to prophylaxis after any sensitising event and postnatally if the baby is RhD-positive.', 1),
('ca000000-0000-0000-0000-000000000050', 'The goal of anti-D prophylaxis is to prevent maternal sensitisation to fetal RhD-positive red cells, which could otherwise cause haemolytic disease of the newborn in current or future pregnancies.', 2),
('ca000000-0000-0000-0000-000000000050', 'Anti-D immunoglobulin is not given if the mother is already sensitised (has detectable anti-D antibodies), since it cannot reverse existing sensitisation.', 3);
